    .{ .name = "caaaar", .doc = "Syntax: (caaaar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (car (car (car pair)))). Accesses the car of\nfour nested car operations on a pair structure.\nExample:\n  (caaaar '((((1 2) 3) 4) 5)) => 1" },
    .{ .name = "caaadr", .doc = "Syntax: (caaadr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (car (car (cdr pair)))). Accesses the car of\nthe car of the car of the cdr of a nested pair structure.\nExample:\n  (caaadr '(1 ((2 3) 4) 5)) => 2" },
    .{ .name = "caaar", .doc = "Syntax: (caaar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (car (car pair))). Accesses the car of the\ncar of the car of a nested pair structure.\nExample:\n  (caaar '(((1 2) 3) 4)) => 1" },
    .{ .name = "caadar", .doc = "Syntax: (caadar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (car (cdr (car pair)))). Accesses the car of\nthe car of the cdr of the car of a nested pair structure.\nExample:\n  (caadar '((1 (2 3)) 4)) => 2" },
    .{ .name = "caaddr", .doc = "Syntax: (caaddr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (car (cdr (cdr pair)))). Accesses the car of\nthe car of the third tail of a nested pair structure.\nExample:\n  (caaddr '(1 2 (3 4) 5)) => 3" },
    .{ .name = "caadr", .doc = "Syntax: (caadr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (car (cdr pair))). Accesses the car of the\ncar of the cdr of a nested pair structure.\nExample:\n  (caadr '(1 (2 3) 4)) => 2" },
    .{ .name = "caar", .doc = "Syntax: (caar pair)\nLibrary: (scheme base)\nDescription: Returns the car of the car of pair. Equivalent to (car (car pair)).\nExample:\n  (caar '((a b) c)) => a" },
    .{ .name = "cadaar", .doc = "Syntax: (cadaar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (cdr (car (car pair)))). Accesses the car of\nthe cdr of the car of the car of a nested pair structure.\nExample:\n  (cadaar '(((1 2) 3) 4)) => 2" },
    .{ .name = "cadadr", .doc = "Syntax: (cadadr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (cdr (car (cdr pair)))). Accesses the car of\nthe cdr of the car of the cdr of a nested pair structure.\nExample:\n  (cadadr '(1 (2 3) 4)) => 3" },
    .{ .name = "cadar", .doc = "Syntax: (cadar pair)\nLibrary: (scheme cxr)\nDescription: Returns the car of the cdr of the car of pair. Equivalent to (car (cdr (car pair))).\nExample:\n  (cadar '((a b) c)) => b" },
    .{ .name = "caddar", .doc = "Syntax: (caddar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (cdr (cdr (car pair)))). Accesses the car of\nthe cdr of the cdr of the car of a nested pair structure.\nExample:\n  (caddar '((1 2 3) 4)) => 3" },
    .{ .name = "cadddr", .doc = "Syntax: (cadddr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (car (cdr (cdr (cdr pair)))). Returns the fourth\nelement of a list.\nExample:\n  (cadddr '(1 2 3 4 5)) => 4" },
    .{ .name = "caddr", .doc = "Syntax: (caddr pair)\nLibrary: (scheme base)\nDescription: Returns the car of the cdr of the cdr of pair. Equivalent to (car (cdr (cdr pair))). This is the third element of a list.\nExample:\n  (caddr '(1 2 3)) => 3" },
    .{ .name = "cadr", .doc = "Syntax: (cadr pair)\nLibrary: (scheme base)\nDescription: Returns the car of the cdr of pair. Equivalent to (car (cdr pair)).\nExample:\n  (cadr '(a b c)) => b" },
    .{ .name = "call-with-current-continuation", .doc = "Syntax: (call-with-current-continuation proc)\nLibrary: (scheme base)\nDescription: Calls proc with the current continuation as its argument.\n  The continuation is a procedure that, when called with a value, returns\n  that value to the point where call/cc was invoked.\nExample:\n  (call-with-current-continuation (lambda (k) (k 42))) => 42" },
    .{ .name = "call-with-values", .doc = "Syntax: (call-with-values producer consumer)\nLibrary: (scheme base)\nDescription: Calls producer with no arguments. The producer must return\n  zero or more values. The consumer is then called with those values as\n  arguments. Returns the result of consumer.\nExample:\n  (call-with-values (lambda () (values 1 2)) +) => 3" },
    .{ .name = "car", .doc = "Syntax: (car pair)\nLibrary: (scheme base)\nDescription: Returns the car of pair. It is an error if pair is not a pair.\nExample:\n  (car '(a b c)) => a\n  (car '((a) b)) => (a)" },
    .{ .name = "cdaaar", .doc = "Syntax: (cdaaar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (car (car (car pair)))). Accesses the cdr of\nthe car of the car of the car of a nested pair structure.\nExample:\n  (cdaaar '((((1 2) 3) 4) 5)) => (2)" },
    .{ .name = "cdaadr", .doc = "Syntax: (cdaadr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (car (car (cdr pair)))). Accesses the cdr of\nthe car of the car of the cdr of a nested pair structure.\nExample:\n  (cdaadr '(1 ((2 3) 4) 5)) => (3)" },
    .{ .name = "cdaar", .doc = "Syntax: (cdaar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (car (car pair))). Accesses the cdr of the\ncar of the car of a nested pair structure.\nExample:\n  (cdaar '(((1 2) 3) 4)) => (2)" },
    .{ .name = "cdadar", .doc = "Syntax: (cdadar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (car (cdr (car pair)))). Accesses the cdr of\nthe car of the cdr of the car of a nested pair structure.\nExample:\n  (cdadar '((1 (2 3)) 4)) => (3)" },
    .{ .name = "cdaddr", .doc = "Syntax: (cdaddr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (car (cdr (cdr pair)))). Accesses the cdr of\nthe car of the third tail of a nested pair structure.\nExample:\n  (cdaddr '(1 2 (3 4) 5)) => (4)" },
    .{ .name = "cdadr", .doc = "Syntax: (cdadr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (car (cdr pair))). Accesses the cdr of the\ncar of the cdr of a nested pair structure.\nExample:\n  (cdadr '(1 (2 3) 4)) => (3)" },
    .{ .name = "cdar", .doc = "Syntax: (cdar pair)\nLibrary: (scheme base)\nDescription: Returns the cdr of the car of pair. Equivalent to (cdr (car pair)).\nExample:\n  (cdar '((1 2) 3)) => (2)" },
    .{ .name = "cddaar", .doc = "Syntax: (cddaar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (cdr (car (car pair)))). Accesses the cdr of\nthe cdr of the car of the car of a nested pair structure.\nExample:\n  (cddaar '(((1 2 3) 4) 5)) => (3)" },
    .{ .name = "cddadr", .doc = "Syntax: (cddadr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (cdr (car (cdr pair)))). Accesses the cdr of\nthe cdr of the car of the cdr of a nested pair structure.\nExample:\n  (cddadr '(1 (2 3 4) 5)) => (4)" },
    .{ .name = "cddar", .doc = "Syntax: (cddar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (cdr (car pair))). Accesses the cdr of the\ncdr of the car of a nested pair structure.\nExample:\n  (cddar '((1 2 3) 4)) => (3)" },
    .{ .name = "cdddar", .doc = "Syntax: (cdddar pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (cdr (cdr (car pair)))). Accesses the cdr of\nthe cdr of the cdr of the car of a nested pair structure.\nExample:\n  (cdddar '((1 2 3 4) 5)) => (4)" },
    .{ .name = "cddddr", .doc = "Syntax: (cddddr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (cdr (cdr (cdr pair)))). Returns the tail of\na list starting after the fourth element.\nExample:\n  (cddddr '(1 2 3 4 5 6)) => (5 6)" },
    .{ .name = "cdddr", .doc = "Syntax: (cdddr pair)\nLibrary: (scheme cxr)\nDescription: Equivalent to (cdr (cdr (cdr pair))). Returns the tail of a\nlist starting after the third element.\nExample:\n  (cdddr '(1 2 3 4 5)) => (4 5)" },
    .{ .name = "cddr", .doc = "Syntax: (cddr pair)\nLibrary: (scheme base)\nDescription: Returns the cdr of the cdr of pair. Equivalent to (cdr (cdr pair)).\nExample:\n  (cddr '(1 2 3)) => (3)" },
    .{ .name = "cdr", .doc = "Syntax: (cdr pair)\nLibrary: (scheme base)\nDescription: Returns the cdr of pair. It is an error if pair is not a pair.\nExample:\n  (cdr '((a) b c)) => (b c)\n  (cdr '(1 . 2)) => 2" },
    .{ .name = "ceiling", .doc = "Syntax: (ceiling z)\nLibrary: (scheme base)\nDescription: Returns the smallest integer not smaller than z (rounds toward positive infinity).\nExample:\n  (ceiling 1.2) => 2.0\n  (ceiling -1.2) => -1.0\n  (ceiling 3) => 3" },
    .{ .name = "chacha20-port-state", .doc = "Syntax: (chacha20-port-state port)\nLibrary: (srfi 271 determinized)\nDescription: Returns the position of the ChaCha20 port as a vector\n  #(key counter offset): the next byte read is byte offset of keystream\n  block counter. A byte taken by peek-u8 counts as not yet read.\nExample:\n  (chacha20-port-state (make-chacha20-port (make-bytevector 32 0) 0 5))\n    => #(#u8(0 ...) 0 5)" },
    .{ .name = "chacha20-port?", .doc = "Syntax: (chacha20-port? obj)\nLibrary: (srfi 271 determinized)\nDescription: Returns #t if obj is a port made by make-chacha20-port.\nExample:\n  (chacha20-port? (make-chacha20-port (make-bytevector 32 1) 0 0)) => #t" },
    .{ .name = "chacha20poly1305-decrypt", .doc = "Syntax: (chacha20poly1305-decrypt key nonce ciphertext [aad])\nLibrary: (scm crypto)\nDescription: Decrypts ciphertext using ChaCha20-Poly1305. key must be 32 bytes; nonce must be 12 bytes. The ciphertext argument must include the 16-byte authentication tag appended at the end. Raises an error if authentication fails.\nExample:\n  (chacha20poly1305-decrypt key nonce ciphertext-with-tag) => #u8(...)" },
    .{ .name = "chacha20poly1305-encrypt", .doc = "Syntax: (chacha20poly1305-encrypt key nonce plaintext [aad])\nLibrary: (scm crypto)\nDescription: Encrypts plaintext using ChaCha20-Poly1305. key must be 32 bytes; nonce must be 12 bytes. Optional aad is additional authenticated data. Returns ciphertext concatenated with 16-byte authentication tag.\nExample:\n  (chacha20poly1305-encrypt key nonce plaintext) => #u8(...)" },
    .{ .name = "char->integer", .doc = "Syntax: (char->integer char)\nLibrary: (scheme base)\nDescription: Returns the Unicode scalar value (codepoint) of the given character as an exact integer.\nExample:\n  (char->integer #\\a) => 97\n  (char->integer #\\A) => 65" },
    .{ .name = "char-alphabetic?", .doc = "Syntax: (char-alphabetic? char)\nLibrary: (scheme char)\nDescription: Returns #t if char is an alphabetic character.\nExample:\n  (char-alphabetic? #\\a) => #t\n  (char-alphabetic? #\\1) => #f" },
    .{ .name = "char-downcase", .doc = "Syntax: (char-downcase char)\nLibrary: (scheme char)\nDescription: Returns the lowercase equivalent of char if it exists, otherwise returns char.\nExample:\n  (char-downcase #\\A) => #\\a\n  (char-downcase #\\a) => #\\a" },
    .{ .name = "char-foldcase", .doc = "Syntax: (char-foldcase char)\nLibrary: (scheme char)\nDescription: Returns the case-folded equivalent of char (for case-insensitive comparisons). Applies Unicode full case folding.\nExample:\n  (char-foldcase #\\A) => #\\a\n  (char-foldcase #\\a) => #\\a" },
    .{ .name = "char-lower-case?", .doc = "Syntax: (char-lower-case? char)\nLibrary: (scheme char)\nDescription: Returns #t if char is a lowercase character.\nExample:\n  (char-lower-case? #\\a) => #t\n  (char-lower-case? #\\A) => #f" },
    .{ .name = "char-numeric?", .doc = "Syntax: (char-numeric? char)\nLibrary: (scheme char)\nDescription: Returns #t if char is a numeric character (digit).\nExample:\n  (char-numeric? #\\5) => #t\n  (char-numeric? #\\a) => #f" },
    .{ .name = "char-upcase", .doc = "Syntax: (char-upcase char)\nLibrary: (scheme char)\nDescription: Returns the uppercase equivalent of char if it exists, otherwise returns char.\nExample:\n  (char-upcase #\\a) => #\\A\n  (char-upcase #\\A) => #\\A" },
    .{ .name = "char-upper-case?", .doc = "Syntax: (char-upper-case? char)\nLibrary: (scheme char)\nDescription: Returns #t if char is an uppercase character.\nExample:\n  (char-upper-case? #\\A) => #t\n  (char-upper-case? #\\a) => #f" },
    .{ .name = "char-whitespace?", .doc = "Syntax: (char-whitespace? char)\nLibrary: (scheme char)\nDescription: Returns #t if char is a whitespace character (space, tab, newline, etc.).\nExample:\n  (char-whitespace? #\\space) => #t\n  (char-whitespace? #\\a) => #f" },
    .{ .name = "char-width", .doc = "Syntax: (char-width c)\nLibrary: (scm terminal)\nDescription: Returns the number of terminal columns the character or\ncode point c occupies: 2 for East Asian wide and fullwidth characters\nand wide emoji, 0 for combining marks, format characters and other\nzero-width characters, -1 for C0 and C1 control characters, and 1\notherwise. c may be a char or an integer code point (needed above\n#xFFFF, which a single char cannot hold); a lone surrogate counts as 1.\nExample:\n  (char-width #\\a) => 1\n  (char-width (integer->char #x4E2D)) => 2\n  (char-width #x1F600) => 2\n  (char-width (integer->char #x301)) => 0" },
    .{ .name = "char<=?", .doc = "Syntax: (char<=? char1 char2 char3 ...)\nLibrary: (scheme base)\nDescription: Returns #t if the character arguments are monotonically non-decreasing.\nExample:\n  (char<=? #\\a #\\b) => #t\n  (char<=? #\\a #\\a) => #t" },
    .{ .name = "char<?", .doc = "Syntax: (char<? char1 char2 char3 ...)\nLibrary: (scheme base)\nDescription: Returns #t if the character arguments are monotonically increasing.\nExample:\n  (char<? #\\a #\\b) => #t\n  (char<? #\\a #\\a) => #f" },
    .{ .name = "char=?", .doc = "Syntax: (char=? char1 char2 char3 ...)\nLibrary: (scheme base)\nDescription: Returns #t if all the given characters are the same (case-sensitive comparison).\nExample:\n  (char=? #\\a #\\a) => #t\n  (char=? #\\a #\\A) => #f" },
    .{ .name = "char>=?", .doc = "Syntax: (char>=? char1 char2 char3 ...)\nLibrary: (scheme base)\nDescription: Returns #t if the character arguments are monotonically non-increasing.\nExample:\n  (char>=? #\\b #\\a) => #t\n  (char>=? #\\a #\\a) => #t" },
    .{ .name = "char>?", .doc = "Syntax: (char>? char1 char2 char3 ...)\nLibrary: (scheme base)\nDescription: Returns #t if the character arguments are monotonically decreasing.\nExample:\n  (char>? #\\b #\\a) => #t\n  (char>? #\\a #\\a) => #f" },
    .{ .name = "char?", .doc = "Syntax: (char? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a character, otherwise returns #f.\nExample:\n  (char? #\\a) => #t\n  (char? \"a\") => #f" },
    .{ .name = "close-input-port", .doc = "Syntax: (close-input-port port)\nLibrary: (scheme base)\nDescription: Closes the input port, releasing any resources. It is an error to read from a closed port.\nExample:\n  (let ((p (open-input-file \"data.txt\")))\n    (close-input-port p))" },
    .{ .name = "close-input-zip", .doc = "Syntax: (close-input-zip zip)\nLibrary: (scm zip)\nDescription: Closes the given ZIP input archive, releasing all underlying resources.\nExample:\n  (let ((z (open-input-zip-file \"archive.zip\")))\n    (close-input-zip z))" },
    .{ .name = "close-json", .doc = "Syntax: (close-json reader)\nLibrary: (scm core)\nDescription: Closes the given JSON reader, releasing any underlying resources.\nExample:\n  (let ((r (open-json-file \"data.json\")))\n    (close-json r))" },
    .{ .name = "close-output-port", .doc = "Syntax: (close-output-port port)\nLibrary: (scheme base)\nDescription: Closes the output port, flushing any buffered output and releasing resources.\nExample:\n  (let ((p (open-output-file \"out.txt\")))\n    (close-output-port p))" },
    .{ .name = "close-output-zip", .doc = "Syntax: (close-output-zip zip)\nLibrary: (scm core)\nDescription: Closes the given zip output archive, flushing and releasing all underlying resources.\nExample:\n  (let ((z (open-output-zip-file \"archive.zip\")))\n    (close-output-zip z))" },
    .{ .name = "close-random-access-file", .doc = "Syntax: (close-random-access-file f)\nLibrary: (scm random access)\nDescription: Closes random-access file f, flushing and releasing the underlying file. Closing an already-closed handle is harmless. Returns an unspecified value.\nExample:\n  (close-random-access-file f)" },
    .{ .name = "close-xml", .doc = "Syntax: (close-xml reader)\nLibrary: (scm core)\nDescription: Closes the given XML reader, releasing any underlying file or stream resources.\nExample:\n  (let ((r (open-xml-file \"data.xml\")))\n    (close-xml r))" },
    .{ .name = "command-line", .doc = "Syntax: (command-line)\nLibrary: (scheme process-context)\nDescription: Returns the command line passed to the process as a list of strings. The first element is typically the program name.\nExample:\n  (command-line) => (\"prog\" \"arg1\" \"arg2\")" },
    .{ .name = "complex-angle", .doc = "Syntax: (complex-angle z)\nLibrary: (scm core)\nDescription: Returns the angle (argument) of the complex number z in radians.\nExample:\n  (complex-angle 1+1i) => 0.7853981633974483" },
    .{ .name = "complex-imag-part", .doc = "Syntax: (complex-imag-part z)\nLibrary: (scm core)\nDescription: Returns the imaginary part of the complex number z.\nExample:\n  (complex-imag-part 1+2i) => 2" },
    .{ .name = "complex-magnitude", .doc = "Syntax: (complex-magnitude z)\nLibrary: (scm core)\nDescription: Returns the magnitude of the complex number z.\nExample:\n  (complex-magnitude 3+4i) => 5.0" },
    .{ .name = "complex-real-part", .doc = "Syntax: (complex-real-part z)\nLibrary: (scm core)\nDescription: Returns the real part of the complex number z.\nExample:\n  (complex-real-part 1+2i) => 1" },
    .{ .name = "complex?", .doc = "Syntax: (complex? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a complex number, #f otherwise.\n  In the R7RS numeric tower, all numbers are complex.\nExample:\n  (complex? 3+4i) => #t\n  (complex? 3)    => #t" },
    .{ .name = "condition-variable-broadcast!", .doc = "Syntax: (condition-variable-broadcast! cv)\nLibrary: (srfi 18)\nDescription: Broadcasts the condition variable, waking all waiting threads.\nExample:\n  (condition-variable-broadcast! cv)" },
    .{ .name = "condition-variable-name", .doc = "Syntax: (condition-variable-name cv)\nLibrary: (srfi 18)\nDescription: Returns the name of the condition variable.\nExample:\n  (condition-variable-name (make-condition-variable 'cv)) => cv" },
    .{ .name = "condition-variable-signal!", .doc = "Syntax: (condition-variable-signal! cv)\nLibrary: (srfi 18)\nDescription: Signals the condition variable, waking one waiting thread.\nExample:\n  (condition-variable-signal! cv)" },
    .{ .name = "condition-variable-specific", .doc = "Syntax: (condition-variable-specific cv)\nLibrary: (srfi 18)\nDescription: Returns the condition-variable-specific data.\nExample:\n  (condition-variable-specific (make-condition-variable)) => ()" },
    .{ .name = "condition-variable-specific-set!", .doc = "Syntax: (condition-variable-specific-set! cv obj)\nLibrary: (srfi 18)\nDescription: Sets the condition-variable-specific data to obj.\nExample:\n  (condition-variable-specific-set! cv 42)" },
    .{ .name = "condition-variable?", .doc = "Syntax: (condition-variable? obj)\nLibrary: (srfi 18)\nDescription: Returns #t if obj is a condition variable.\nExample:\n  (condition-variable? (make-condition-variable)) => #t" },
    .{ .name = "cons", .doc = "Syntax: (cons obj1 obj2)\nLibrary: (scheme base)\nDescription: Returns a newly allocated pair whose car is obj1 and whose cdr is obj2.\nExample:\n  (cons 'a '()) => (a)\n  (cons 'a '(b c)) => (a b c)\n  (cons 1 2) => (1 . 2)" },
    .{ .name = "console-echo!", .doc = "Syntax: (console-echo! enable)\nLibrary: (scm terminal)\nDescription: Enables or disables echoing of typed characters\non the terminal. Unlike terminal-raw!, line buffering and\nsignal processing are left untouched, so the user can still\nedit the line and press enter before it is delivered. The\nprimary use is reading a password.\nReturns #t on success, #f if not supported (e.g. when stdin\nis not a terminal). On the Java implementation under\nWindows, console-echo! returns #f because stty is not\navailable there — use console-read-password instead.\nA shutdown hook restores echo on exit.\nExample:\n  (console-echo! #f)  ; disable echo\n  (read-line)         ; read password silently\n  (console-echo! #t)  ; re-enable echo" },
    .{ .name = "console-read-password", .doc = "Syntax: (console-read-password)\nSyntax: (console-read-password prompt)\nLibrary: (scm terminal)\nDescription: Reads a line from the terminal without echoing\nthe typed characters. If prompt is given, it is displayed\nbefore reading. Returns the entered string (without the\ntrailing newline), or the eof-object if input is closed.\nWhen stdin is redirected, this falls back to read-line\nbehaviour on the underlying stream.\nExample:\n  (console-read-password \"Password: \")" },
    .{ .name = "copy-directory", .doc = "Syntax: (copy-directory src dest)\nLibrary: (scm fs)\nDescription: Recursively copies the directory at src to dest. Returns unspecified on success, #f on failure.\nExample:\n  (copy-directory \"/src/dir\" \"/dst/dir\")" },
    .{ .name = "copy-file", .doc = "Syntax: (copy-file src dest)\nLibrary: (scm fs)\nDescription: Copies the file at src to dest, overwriting dest if it exists. Returns unspecified on success, #f on failure.\nExample:\n  (copy-file \"data.txt\" \"backup.txt\")" },
    .{ .name = "cos", .doc = "Syntax: (cos z)\nLibrary: (scheme inexact)\nDescription: Returns the cosine of z. The argument is in radians.\nExample:\n  (cos 0.0) => 1.0\n  (cos 3.141592653589793) => -1.0" },
    .{ .name = "crc32", .doc = "Syntax: (crc32 bytevector [start [end]])\nLibrary: (scm png)\nDescription: Computes the IEEE CRC-32 checksum (polynomial 0xEDB88320,\n  as used by PNG, gzip, zip) of bytevector and returns it as an exact\n  non-negative integer in [0, 2^32).\nExample:\n  (crc32 (string->utf8 \"123456789\")) => 3421780262" },
    .{ .name = "csv-line->fields", .doc = "Syntax: (csv-line->fields str sep) (csv-line->fields str sep 'trim)\nLibrary: (scm core)\nDescription: Splits a CSV line string using the given separator, stripping surrounding double-quotes from each field, and returns the fields as a vector. When 'trim is given as a third argument, also trims whitespace from each field.\nExample:\n  (csv-line->fields \"a,b,c\" \",\") => #(\"a\" \"b\" \"c\")\n  (csv-line->fields \"\\\"hello\\\",world\" \",\") => #(\"hello\" \"world\")" },
    .{ .name = "current-directory", .doc = "Syntax: (current-directory)\nLibrary: (scm fs)\nDescription: Returns the current working directory as a string.\nExample:\n  (current-directory) => \"/home/user/projects\"" },
    .{ .name = "current-pid", .doc = "Syntax: (current-pid)\nLibrary: (scm system)\nDescription: Returns the OS process id of the current Scheme process.\nExample:\n  (current-pid) => 12345" },
    .{ .name = "current-source-location", .doc = "Syntax: (current-source-location)\nLibrary: (scm core)\nDescription: Returns the source position of the call site as (filename line column), or #f if no position is available.\nExample:\n  (current-source-location) => (\"file.scm\" 42 0)" },
    .{ .name = "current-thread", .doc = "Syntax: (current-thread)\nLibrary: (srfi 18)\nDescription: Returns the current thread object.\nExample:\n  (thread? (current-thread)) => #t" },
    .{ .name = "deflate-compress", .doc = "Syntax: (deflate-compress bytevector [level])\nLibrary: (scm compression)\nDescription: Compresses bytevector using raw DEFLATE (RFC 1951) and returns\n  a bytevector. The optional level is an integer 0-9: 0 = no compression,\n  1-3 = fastest, 4-6 = optimal (default), 7-9 = smallest size.\nExample:\n  (utf8->string (deflate-decompress (deflate-compress (string->utf8 \"hello\")))) => \"hello\"" },
    .{ .name = "deflate-decompress", .doc = "Syntax: (deflate-decompress bytevector)\nLibrary: (scm compression)\nDescription: Decompresses a raw DEFLATE-compressed (RFC 1951) bytevector\n  and returns the original bytevector.\nExample:\n  (utf8->string (deflate-decompress (deflate-compress (string->utf8 \"hello\")))) => \"hello\"" },
    .{ .name = "delete-directory", .doc = "Syntax: (delete-directory dir)\nLibrary: (scm fs)\nDescription: Recursively deletes the directory at dir. Returns unspecified on success, #f on failure.\nExample:\n  (delete-directory \"/tmp/old-dir\")" },
    .{ .name = "delete-file", .doc = "Syntax: (delete-file filename)\nLibrary: (scheme file)\nDescription: Deletes the named file. Returns unspecified if successful, #f if the file could not be deleted.\nExample:\n  (delete-file \"temp.txt\")" },
    .{ .name = "dict-clear", .doc = "Syntax: (dict-clear d)\nLibrary: (scm core)\nDescription: Removes all key-value associations from the dictionary d, leaving it empty.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"key\" 1)\n    (dict-clear d)\n    (dict-size d)) => 0" },
    .{ .name = "dict-contains", .doc = "Syntax: (dict-contains d key)\nLibrary: (scm core)\nDescription: Returns #t if the dictionary d contains an entry for key (a string or symbol), otherwise returns #f.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"x\" 42)\n    (dict-contains d \"x\")) => #t" },
    .{ .name = "dict-entries", .doc = "Syntax: (dict-entries d)\nLibrary: (scm core)\nDescription: Returns a list of (key . value) pairs for all entries in the dictionary d.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"a\" 1)\n    (dict-entries d)) => ((\"a\" . 1))" },
    .{ .name = "dict-get", .doc = "Syntax: (dict-get d key) (dict-get d key default)\nLibrary: (scm core)\nDescription: Returns the value associated with key in the dictionary d. If the key is not found and a default is given, returns it; otherwise raises an error.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"x\" 42)\n    (dict-get d \"x\")) => 42" },
    .{ .name = "dict-keys", .doc = "Syntax: (dict-keys d)\nLibrary: (scm core)\nDescription: Returns a list of all keys (as strings) in the dictionary d.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"a\" 1)\n    (dict-put d \"b\" 2)\n    (dict-keys d)) => (\"a\" \"b\")" },
    .{ .name = "dict-put", .doc = "Syntax: (dict-put d key value)\nLibrary: (scm core)\nDescription: Associates key (a string or symbol) with value in the dictionary d. If the key already exists, the old value is replaced.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"x\" 42)\n    (dict-get d \"x\")) => 42" },
    .{ .name = "dict-size", .doc = "Syntax: (dict-size d)\nLibrary: (scm core)\nDescription: Returns the number of key-value entries in the dictionary d.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"a\" 1)\n    (dict-size d)) => 1" },
    .{ .name = "dict-values", .doc = "Syntax: (dict-values d)\nLibrary: (scm core)\nDescription: Returns a list of all values in the dictionary d.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"a\" 1)\n    (dict-values d)) => (1)" },
    .{ .name = "digit-value", .doc = "Syntax: (digit-value char)\nLibrary: (scheme char)\nDescription: Returns the numeric value (0-9) of a Unicode decimal digit character, or #f if the character is not a decimal digit.\nExample:\n  (digit-value #\\3) => 3\n  (digit-value #\\a) => #f" },
    .{ .name = "directory-directories", .doc = "Syntax: (directory-directories dirname)\nLibrary: (scm fs)\nDescription: Returns a list of subdirectory names (not full paths) in the directory dirname.\nExample:\n  (directory-directories \"/usr\") => (\"bin\" \"lib\" \"share\" ...)" },
    .{ .name = "directory-entries", .doc = "Syntax: (directory-entries dirname)\nLibrary: (scm fs)\nDescription: Returns a list of (name . type) pairs for the entries in dirname, where name is the entry name (not a full path) and type is one of the symbols file, directory, or symlink. Symlinks are reported as symlink regardless of what they point to (they are not followed).\nExample:\n  (directory-entries \"/tmp\") => ((\"a.txt\" . file) (\"sub\" . directory) (\"link\" . symlink) ...)" },
    .{ .name = "directory-exists?", .doc = "Syntax: (directory-exists? dirname)\nLibrary: (scm fs)\nDescription: Returns #t if the given path names an existing directory, otherwise returns #f.\nExample:\n  (directory-exists? \"/tmp\") => #t\n  (directory-exists? \"/nonexistent\") => #f" },
    .{ .name = "directory-files", .doc = "Syntax: (directory-files dirname)\nLibrary: (scm fs)\nDescription: Returns a list of file names (not full paths) in the directory dirname.\nExample:\n  (directory-files \"/tmp\") => (\"file1.txt\" \"file2.txt\" ...)" },
    .{ .name = "directory-name", .doc = "Syntax: (directory-name path)\nLibrary: (scm fs)\nDescription: Returns the directory part of the given path as an absolute path string, or #f if there is no parent directory.\nExample:\n  (directory-name \"/usr/share/readme.txt\") => \"/usr/share\"" },
    .{ .name = "display", .doc = "Syntax: (display obj) (display obj port)\nLibrary: (scheme write)\nDescription: Writes a human-readable representation of obj to the current output port or the given port. Strings are written without quotes; characters are written without the #\\ prefix.\nExample:\n  (display \"hello\") => hello\n  (display #\\a) => a" },
    .{ .name = "eof-object?", .doc = "Syntax: (eof-object? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is an end-of-file object, otherwise returns #f.\nExample:\n  (eof-object? (read (open-input-string \"\"))) => #t" },
    .{ .name = "eq?", .doc = "Syntax: (eq? obj1 obj2)\nLibrary: (scheme base)\nDescription: Returns #t if obj1 and obj2 are the same object. Equivalent to pointer equality for most types.\nExample:\n  (eq? 'a 'a) => #t\n  (eq? '() '()) => #t\n  (eq? (list 1) (list 1)) => #f" },
    .{ .name = "equal?", .doc = "Syntax: (equal? obj1 obj2)\nLibrary: (scheme base)\nDescription: Returns #t if obj1 and obj2 have the same structure and contents (deep equality). Recursively compares pairs, vectors, and strings.\nExample:\n  (equal? '(a b c) '(a b c)) => #t\n  (equal? \"abc\" \"abc\") => #t\n  (equal? '(a b) '(a c)) => #f" },
    .{ .name = "eqv?", .doc = "Syntax: (eqv? obj1 obj2)\nLibrary: (scheme base)\nDescription: Returns #t if obj1 and obj2 are operationally equivalent. Numbers are eqv? if they have the same exactness and are numerically equal.\nExample:\n  (eqv? 'a 'a) => #t\n  (eqv? 1 1) => #t\n  (eqv? 1 1.0) => #f" },
    .{ .name = "error", .doc = "Syntax: (error message obj ...) (error who message obj ...)\nLibrary: (scheme base)\nDescription: Raises an error. In R7RS form, message is a string and obj ... are irritants. In SRFI-23 form, who is a symbol identifying the caller.\nExample:\n  (error \"out of range\" 42)\n  (error 'my-proc \"value out of range\" 42)" },
    .{ .name = "error-object-irritants", .doc = "Syntax: (error-object-irritants error-object)\nLibrary: (scheme base)\nDescription: Returns the list of irritants (extra objects) of the given error object.\nExample:\n  (guard (e (#t (error-object-irritants e)))\n    (error \"bad value\" 42)) => (42)" },
    .{ .name = "error-object-message", .doc = "Syntax: (error-object-message error-object)\nLibrary: (scheme base)\nDescription: Returns the message string of the given error object.\nExample:\n  (guard (e (#t (error-object-message e)))\n    (error \"bad value\" 42)) => \"bad value\"" },
    .{ .name = "error-object?", .doc = "Syntax: (error-object? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is an error object (as raised by error), otherwise returns #f.\nExample:\n  (guard (e (#t (error-object? e)))\n    (error \"oops\")) => #t" },
    .{ .name = "exact", .doc = "Syntax: (exact z)\nLibrary: (scheme base)\nDescription: Returns the exact number that is numerically equal to z.\n  For inexact integers, returns the integer. For non-integral inexact\n  numbers, returns the simplest exact rational whose inexact value\n  equals z (using continued fraction approximation).\nExample:\n  (exact 1.5) => 3/2\n  (exact 0.3) => 3/10\n  (exact 3.0) => 3\n  (exact 3) => 3" },
    .{ .name = "exact?", .doc = "Syntax: (exact? z)\nLibrary: (scheme base)\nDescription: Returns #t if z is an exact number (integer or rational), otherwise returns #f.\nExample:\n  (exact? 1) => #t\n  (exact? 1.0) => #f\n  (exact? 1/3) => #t" },
    .{ .name = "exit", .doc = "Syntax: (exit) (exit obj)\nLibrary: (scheme process-context)\nDescription: Terminates the current program. If obj is an exact integer, it is used as the exit code. Without an argument, exits with code 1.\nExample:\n  (exit)\n  (exit 0)" },
    .{ .name = "expt", .doc = "Syntax: (expt z1 z2)\nLibrary: (scheme base)\nDescription: Returns z1 raised to the power z2. If z2 is exact 0, returns exact 1.\nExample:\n  (expt 2 10) => 1024\n  (expt 4 0) => 1\n  (expt 2.0 3) => 8.0" },
    .{ .name = "file-error?", .doc = "Syntax: (file-error? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a file error object (as raised by file operations), otherwise returns #f.\nExample:\n  (guard (e (#t (file-error? e)))\n    (open-input-file \"nonexistent\")) => #t" },
    .{ .name = "file-exists?", .doc = "Syntax: (file-exists? filename)\nLibrary: (scheme file)\nDescription: Returns #t if the named file exists, otherwise returns #f.\nExample:\n  (file-exists? \"/etc/hosts\") => #t\n  (file-exists? \"/nonexistent\") => #f" },
    .{ .name = "file-lock", .doc = "Syntax: (file-lock path)\nLibrary: (scm fs)\nDescription: Acquires an exclusive, OS-managed advisory lock on the file at\n  path, creating the file (and any parent directories) if needed. Returns a\n  lock handle on success, or #f if another process already holds the lock.\n  Release it with file-unlock; the lock is also released automatically when\n  the process exits, so it never goes stale.\nExample:\n  (define h (file-lock \"/tmp/app.lock\"))\n  (when h (file-unlock h))" },
    .{ .name = "file-modification-date", .doc = "Syntax: (file-modification-date filename)\nLibrary: (scm fs)\nDescription: Returns the last modification time of the file as seconds since the Unix epoch (UTC).\nExample:\n  (file-modification-date \"data.txt\") => 1700000000" },
    .{ .name = "file-modification-timestamp", .doc = "Syntax: (file-modification-timestamp filename)\nLibrary: (scm fs)\nDescription: Returns the last modification time of the file as a millisecond timestamp (milliseconds since the Unix epoch, UTC).\nExample:\n  (file-modification-timestamp \"data.txt\") => 1700000000000" },
    .{ .name = "file-size", .doc = "Syntax: (file-size file)\nLibrary: (scm fs)\nDescription: Returns the size of the named file in bytes as an exact integer, or #f if the file cannot be accessed.\nExample:\n  (file-size \"/etc/hosts\") => 221" },
    .{ .name = "file-symlink?", .doc = "Syntax: (file-symlink? path)\nLibrary: (scm fs)\nDescription: Returns #t if path names a symbolic link itself (without following it), otherwise #f. Returns #t even for a dangling link whose target is missing, and #f if path does not exist.\nExample:\n  (file-symlink? \"/usr/local/bin/python\") => #t" },
    .{ .name = "file-unlock", .doc = "Syntax: (file-unlock handle)\nLibrary: (scm fs)\nDescription: Releases a lock acquired by file-lock. Returns #t if handle was a\n  live file lock, #f otherwise.\nExample:\n  (file-unlock (file-lock \"/tmp/app.lock\")) => #t" },
    .{ .name = "first", .doc = "Syntax: (first lst)\nLibrary: (srfi 1)\nDescription: Returns the first element of list lst. Equivalent to car.\nExample:\n  (first '(a b c)) => a" },
    .{ .name = "floor", .doc = "Syntax: (floor z)\nLibrary: (scheme base)\nDescription: Returns the largest integer not larger than z (rounds toward negative infinity).\nExample:\n  (floor 1.8) => 1.0\n  (floor -1.2) => -2.0\n  (floor 3) => 3" },
    .{ .name = "flush-output-port", .doc = "Syntax: (flush-output-port) (flush-output-port port)\nLibrary: (scheme base)\nDescription: Flushes any buffered output in the given output port (or current output port if omitted).\nExample:\n  (flush-output-port)" },
    .{ .name = "format", .doc = "Syntax: (format dest fmt val ...)\nLibrary: (scm io), (srfi 28), (srfi 48)\nDescription: Formats a string by substituting values for format\n  directives in fmt.\n  ~a  display (without quotes)\n  ~s  write (with quotes)\n  ~w  write with shared structure (datum labels)\n  ~d  decimal integer\n  ~x  hexadecimal integer (lowercase, signed)\n  ~o  octal integer (signed)\n  ~b  binary integer (signed)\n  ~c  character\n  ~y  pretty-print\n  ~f  fixed-point float (~W,Df for width W and D decimal places)\n  ~?  recursive format (takes format-string and arg-list)\n  ~k  recursive format (alias for ~?)\n  ~%  newline\n  ~n  newline (alias)\n  ~&  freshline (newline if not at start of line)\n  ~t  tab\n  ~_  space\n  ~~  literal tilde\n  ~h  help (display directive summary)\n  Width/alignment: ~10a (right-align in 10), ~-10a (left-align).\n  dest: #f (return string), #t (current output port), or a port.\nExample:\n  (format #f \"~a + ~a = ~a\" 1 2 3) => \"1 + 2 = 3\"\n  (format #f \"~d in hex is ~x\" 255 255) => \"255 in hex is ff\"" },
    .{ .name = "gensym", .doc = "Syntax: (gensym)\nLibrary: (scm core)\nDescription: Returns a fresh, unique, non-interned symbol. Each call returns a symbol distinct from all previously generated symbols.\nExample:\n  (gensym) => gensym-1\n  (eq? (gensym) (gensym)) => #f" },
    .{ .name = "get-bytes", .doc = "Syntax: (get-bytes obj [encoding])\nLibrary: (scm core)\nDescription: Returns the byte representation of obj (string, symbol, or bytevector) as a bytevector.\n  encoding is an optional string or symbol specifying the character encoding (default: utf-8).\n  Supported encodings: utf-8, utf-8-bom, latin-1, utf-16, utf-16-le.\nExample:\n  (get-bytes \"hello\")\n  (get-bytes \"hello\" \"latin-1\")" },
    .{ .name = "get-environment-variable", .doc = "Syntax: (get-environment-variable name)\nLibrary: (scm system) (scheme process-context) (srfi 98)\nDescription: Returns the value of the environment variable named name as a string, or #f if it is not set.\nExample:\n  (get-environment-variable \"HOME\") => \"/home/user\"\n  (get-environment-variable \"UNDEFINED_VAR\") => #f" },
    .{ .name = "get-environment-variables", .doc = "Syntax: (get-environment-variables)\nLibrary: (scheme process-context)\nDescription: Returns an association list of all environment variables as (name . value) pairs, where both are strings.\nExample:\n  (assoc \"HOME\" (get-environment-variables)) => (\"HOME\" . \"/home/user\")" },
    .{ .name = "get-output-bytevector", .doc = "Syntax: (get-output-bytevector port)\nLibrary: (scheme base)\nDescription: Returns a bytevector consisting of the bytes that have been output to the given bytevector output port (created with open-output-bytevector).\nExample:\n  (let ((p (open-output-bytevector)))\n    (write-u8 65 p)\n    (get-output-bytevector p)) => #u8(65)" },
    .{ .name = "get-output-string", .doc = "Syntax: (get-output-string port)\nLibrary: (scheme base)\nDescription: Returns a string consisting of the characters that have been output to the given string output port (created with open-output-string).\nExample:\n  (let ((p (open-output-string)))\n    (write-char #\\A p)\n    (get-output-string p)) => \"A\"" },
    .{ .name = "get-output-zip-bytevector", .doc = "Syntax: (get-output-zip-bytevector zip)\nLibrary: (scm zip)\nDescription: Returns the contents of an in-memory ZIP archive as a bytevector. Must be called after close-output-zip to ensure all entries are flushed.\nExample:\n  (let ((z (open-output-zip-bytevector)))\n    (close-output-zip z)\n    (get-output-zip-bytevector z))" },
    .{ .name = "get-property", .doc = "Syntax: (get-property lst name) (get-property lst name default)\nLibrary: (scm core)\nDescription: Searches for name in the property list lst. Each element may be a symbol (flag) or a (name value) pair. Returns the value, the symbol itself (for flags), or default/#f if not found.\nExample:\n  (get-property '((x 1) (y 2)) 'x) => 1\n  (get-property '(foo bar) 'foo) => foo" },
    .{ .name = "get-property-list", .doc = "Syntax: (get-property-list lst name) (get-property-list lst name default)\nLibrary: (scm core)\nDescription: Searches for name in the property list lst. Returns the cdr of the matching pair (the full value list), or default/#f if not found.\nExample:\n  (get-property-list '((x 1 2) (y 3)) 'x) => (1 2)" },
    .{ .name = "gzip-compress", .doc = "Syntax: (gzip-compress bytevector [level])\nLibrary: (scm compression)\nDescription: Compresses bytevector using GZip format (RFC 1952) and returns\n  a bytevector. The optional level is an integer 0-9: 0 = no compression,\n  1-3 = fastest, 4-6 = optimal (default), 7-9 = smallest size.\nExample:\n  (utf8->string (gzip-decompress (gzip-compress (string->utf8 \"hello\")))) => \"hello\"" },
    .{ .name = "gzip-decompress", .doc = "Syntax: (gzip-decompress bytevector)\nLibrary: (scm compression)\nDescription: Decompresses a GZip-compressed (RFC 1952) bytevector and returns\n  the original bytevector.\nExample:\n  (utf8->string (gzip-decompress (gzip-compress (string->utf8 \"hello\")))) => \"hello\"" },
    .{ .name = "hash-table->alist", .doc = "Syntax: (hash-table->alist ht)\nLibrary: (srfi 69)\nDescription: Returns an association list of all key-value pairs in the hash table ht. The order is unspecified.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'a 1)\n  (hash-table->alist ht) => ((a . 1))" },
    .{ .name = "hash-table-clear!", .doc = "Syntax: (hash-table-clear! ht)\nLibrary: (srfi 125)\nDescription: Removes all associations from the hash table ht.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'a 1)\n  (hash-table-clear! ht)\n  (hash-table-size ht) => 0" },
    .{ .name = "hash-table-copy", .doc = "Syntax: (hash-table-copy ht)\nLibrary: (srfi 69)\nDescription: Returns a copy of the hash table ht with the same equality mode and all the same key-value associations.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'a 1)\n  (define ht2 (hash-table-copy ht))\n  (hash-table-ref ht2 'a) => 1" },
    .{ .name = "hash-table-delete!", .doc = "Syntax: (hash-table-delete! ht key)\nLibrary: (srfi 69)\nDescription: Removes the association for key from the hash table ht. Has no effect if key is not present.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'x 42)\n  (hash-table-delete! ht 'x)\n  (hash-table-exists? ht 'x) => #f" },
    .{ .name = "hash-table-exists?", .doc = "Syntax: (hash-table-exists? ht key)\nLibrary: (srfi 69)\nDescription: Returns #t if key is associated with a value in ht, #f otherwise.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'x 42)\n  (hash-table-exists? ht 'x) => #t\n  (hash-table-exists? ht 'y) => #f" },
    .{ .name = "hash-table-keys", .doc = "Syntax: (hash-table-keys ht)\nLibrary: (srfi 69)\nDescription: Returns a list of all keys in the hash table ht. The order is unspecified.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'a 1)\n  (hash-table-set! ht 'b 2)\n  (list-sort symbol<? (hash-table-keys ht)) => (a b)" },
    .{ .name = "hash-table-ref", .doc = "Syntax: (hash-table-ref ht key [default-thunk])\nLibrary: (srfi 69)\nDescription: Returns the value associated with key in ht. If the key is not found and default-thunk is provided, calls it and returns the result; otherwise raises an error.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'x 42)\n  (hash-table-ref ht 'x) => 42" },
    .{ .name = "hash-table-ref/default", .doc = "Syntax: (hash-table-ref/default ht key default)\nLibrary: (srfi 69)\nDescription: Returns the value associated with key in ht, or default if key is not found.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'x 42)\n  (hash-table-ref/default ht 'x 0) => 42\n  (hash-table-ref/default ht 'y 0) => 0" },
    .{ .name = "hash-table-set!", .doc = "Syntax: (hash-table-set! ht key value)\nLibrary: (srfi 69)\nDescription: Associates key with value in the hash table ht. If the key already exists, its value is updated.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'x 42)\n  (hash-table-ref ht 'x) => 42" },
    .{ .name = "hash-table-size", .doc = "Syntax: (hash-table-size ht)\nLibrary: (srfi 69)\nDescription: Returns the number of associations in the hash table ht.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'x 1)\n  (hash-table-set! ht 'y 2)\n  (hash-table-size ht) => 2" },
    .{ .name = "hash-table-values", .doc = "Syntax: (hash-table-values ht)\nLibrary: (srfi 69)\nDescription: Returns a list of all values in the hash table ht. The order is unspecified.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'a 1)\n  (hash-table-set! ht 'b 2)\n  (list-sort < (hash-table-values ht)) => (1 2)" },
    .{ .name = "hash-table?", .doc = "Syntax: (hash-table? obj)\nLibrary: (srfi 69)\nDescription: Returns #t if obj is a hash table, #f otherwise.\nExample:\n  (hash-table? (make-hash-table)) => #t\n  (hash-table? '()) => #f" },
    .{ .name = "hmac-sha256", .doc = "Syntax: (hmac-sha256 key data)\nLibrary: (scm crypto)\nDescription: Computes HMAC-SHA256 of data using key. Both key and data must be bytevectors. Returns a bytevector.\nExample:\n  (hmac-sha256 key-bv data-bv) => #u8(...)" },
    .{ .name = "html-escape", .doc = "Syntax: (html-escape s)\nLibrary: (scm html)\nDescription: Escapes the five HTML metacharacters (&, <, >, \", ') in s so the result is safe to splice into HTML text content or attribute values.\nExample:\n  (html-escape \"a < b & c\") => \"a &lt; b &amp; c\"" },
    .{ .name = "image-decode-rgba", .doc = "Syntax: (image-decode-rgba bytevector max-pixels)\nLibrary: (scm image)\nDescription: Decodes a PNG or JPEG image to (width height pixels), pixels\n  a bytevector of straight RGBA, 4 bytes per pixel, rows top to bottom.\n  Signals an error for malformed or unsupported data and for images of\n  more than max-pixels pixels (checked before decoding). Used by\n  image-decode." },
    .{ .name = "image-orient-rgba", .doc = "Syntax: (image-orient-rgba pixels width height orientation)\nLibrary: (scm image)\nDescription: Applies EXIF orientation 1 to 8 to straight RGBA pixels and\n  returns the new pixels (height x width for 5 to 8). Used by\n  image-orient." },
    .{ .name = "image-resize-rgba", .doc = "Syntax: (image-resize-rgba pixels width height new-width new-height method)\nLibrary: (scm image)\nDescription: Resizes straight RGBA pixels; method is 'box (area average)\n  or 'bilinear. Returns the new pixels. Used by image-resize." },
    .{ .name = "inexact", .doc = "Syntax: (inexact z)\nLibrary: (scheme base)\nDescription: Returns the inexact (floating-point) number that is numerically closest to z.\nExample:\n  (inexact 1) => 1.0\n  (inexact 1/3) => 0.3333333333333333" },
    .{ .name = "input-port-open?", .doc = "Syntax: (input-port-open? port)\nLibrary: (scheme base)\nDescription: Returns #t if the input port is still open, otherwise returns #f.\nExample:\n  (let ((p (open-input-string \"abc\")))\n    (close-input-port p)\n    (input-port-open? p)) => #f" },
    .{ .name = "input-port?", .doc = "Syntax: (input-port? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is an input port, otherwise returns #f.\nExample:\n  (input-port? (open-input-string \"abc\")) => #t\n  (input-port? (open-output-string)) => #f" },
    .{ .name = "integer->char", .doc = "Syntax: (integer->char n)\nLibrary: (scheme base)\nDescription: Returns the character corresponding to the given Unicode scalar value (codepoint).\nExample:\n  (integer->char 97) => #\\a\n  (integer->char 65) => #\\A" },
    .{ .name = "integer-length", .doc = "Syntax: (integer-length i)\nLibrary: (srfi 151)\nDescription: Returns the number of bits needed to represent i, not counting\nthe sign bit. For non-negative i, this is the index of the highest set bit\nplus one. For negative i, it is the number of bits in (bitwise-not i).\nExample:\n  (integer-length 0) => 0\n  (integer-length 1) => 1\n  (integer-length 7) => 3\n  (integer-length -1) => 0\n  (integer-length -8) => 3" },
    .{ .name = "integer?", .doc = "Syntax: (integer? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is an integer (exact or inexact with an integer value), otherwise returns #f.\nExample:\n  (integer? 1) => #t\n  (integer? 1.0) => #t\n  (integer? 1.5) => #f" },
    .{ .name = "join-timeout-exception?", .doc = "Syntax: (join-timeout-exception? obj)\nLibrary: (srfi 18)\nDescription: Returns #t if obj is a join-timeout exception.\nExample:\n  (guard (e ((join-timeout-exception? e) 'timeout)) (thread-join! t 0))" },
    .{ .name = "json-attribute", .doc = "Syntax: (json-attribute object name) (json-attribute object name default)\nLibrary: (scm core)\nDescription: Returns the value of the named attribute from a JSON object. Returns default (or #f) if the attribute does not exist.\nExample:\n  (let ((obj (json-next-object reader)))\n    (json-attribute obj 'name \"unknown\"))" },
    .{ .name = "json-next-object", .doc = "Syntax: (json-next-object reader)\nLibrary: (scm core)\nDescription: Reads and returns the next JSON object from the given JSON reader, or #f if there are no more objects.\nExample:\n  (let ((r (open-json-file \"data.json\")))\n    (json-next-object r))" },
    .{ .name = "json-simple->pretty-string", .doc = "Syntax: (json->pretty-string val)\nLibrary: (scm json simple)\nDescription: Returns two-space-indented JSON text for val as a string\n  (see json-write-pretty).\nExample:\n  (json->pretty-string '((\"a\" . 1))) => \"{\\n  \\\"a\\\": 1\\n}\"" },
    .{ .name = "json-simple->string", .doc = "Syntax: (json->string val)\nLibrary: (scm json simple)\nDescription: Returns compact JSON text for val as a string (see json-write).\nExample:\n  (json->string #(1 2 3)) => \"[1,2,3]\"" },
    .{ .name = "json-simple-parse", .doc = "Syntax: (json-parse str)\nLibrary: (scm json simple)\nDescription: Parses the JSON text in string str and returns its Scheme\n  representation: objects as alists with string keys (order preserved),\n  arrays as vectors, strings as strings, integral numbers as exact\n  integers and fractional ones as inexact reals, true/false as #t/#f,\n  and null as the symbol 'null. Raises an error on malformed input.\nExample:\n  (json-parse \"{\\\"a\\\": [1, 2.5, true, null]}\")\n    => ((\"a\" . #(1 2.5 #t null)))" },
    .{ .name = "kill", .doc = "Syntax: (kill pid [force?])\nLibrary: (scm system)\nDescription: Sends a termination request to the process with the given\n  pid. With force? = #f (default) requests a normal termination\n  (SIGTERM on Unix); with force? = #t kills forcefully (SIGKILL on Unix).\n  Returns #t if the request was delivered, #f if the process does not\n  exist or the caller lacks permission to signal it.\nExample:\n  (kill 12345)        ; graceful\n  (kill 12345 #t)     ; force" },
    .{ .name = "lambda?", .doc = "Syntax: (lambda? obj)\nLibrary: (scm core)\nDescription: Returns #t if obj is a compiled lambda (procedure), otherwise returns #f.\nExample:\n  (lambda? (lambda (x) x)) => #t\n  (lambda? 42) => #f" },
    .{ .name = "latin1->string", .doc = "Syntax: (latin1->string bv [start [end]])\nLibrary: (scm bytevector)\nDescription: Decodes the bytes of bv (or its range from start to end)\nas ISO-8859-1 (Latin-1): each byte becomes the character with the same\ncode. Never fails.\nExample:\n  (latin1->string (bytevector #x61 #xE4)) => \"a\\xE4;\"" },
    .{ .name = "length", .doc = "Syntax: (length list)\nLibrary: (scheme base)\nDescription: Returns the number of elements in the proper list. It is an error if the list is not a proper list.\nExample:\n  (length '(a b c)) => 3\n  (length '()) => 0" },
    .{ .name = "list", .doc = "Syntax: (list obj ...)\nLibrary: (scheme base)\nDescription: Returns a newly allocated list of its arguments.\nExample:\n  (list 'a (+ 3 4) 'c) => (a 7 c)\n  (list) => ()" },
    .{ .name = "list-ref", .doc = "Syntax: (list-ref list k)\nLibrary: (scheme base)\nDescription: Returns the k-th element (zero-indexed) of list. It is an error if k is out of range.\nExample:\n  (list-ref '(a b c) 0) => a\n  (list-ref '(a b c) 2) => c" },
    .{ .name = "list?", .doc = "Syntax: (list? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a proper list (a sequence of pairs terminated by the empty list), otherwise returns #f. Also detects circular lists.\nExample:\n  (list? '(a b c)) => #t\n  (list? '(a . b)) => #f\n  (list? '()) => #t" },
    .{ .name = "log", .doc = "Syntax: (log z) (log z base)\nLibrary: (scheme inexact)\nDescription: Returns the natural logarithm of z, or the logarithm of z to base if given.\nExample:\n  (log 1.0) => 0.0\n  (log 8.0 2.0) => 3.0" },
    .{ .name = "macroexpand", .doc = "Syntax: (macroexpand expr)\nLibrary: (scm core)\nDescription: Fully expands all macros in expr using the Dybvig expander.\nReturns a plain S-expression with all macros expanded.\nExample:\n  (macroexpand '(and 1 2 3)) => (if 1 (and 2 3) #f)" },
    .{ .name = "make-bytevector", .doc = "Syntax: (make-bytevector k) (make-bytevector k fill)\nLibrary: (scheme base)\nDescription: Returns a newly allocated bytevector of k bytes. If fill is given, each byte is initialized to fill (0-255); otherwise each byte is 0.\nExample:\n  (make-bytevector 3) => #u8(0 0 0)\n  (make-bytevector 3 5) => #u8(5 5 5)" },
    .{ .name = "make-chacha20-port", .doc = "Syntax: (make-chacha20-port key counter offset)\nLibrary: (srfi 271 determinized)\nDescription: Returns a binary input port delivering the endless ChaCha20\n  keystream for the 32-byte bytevector key (all-zero nonce), starting at\n  byte offset (0..63) of block counter (0..2^63-1).\nExample:\n  (read-u8 (make-chacha20-port (make-bytevector 32 0) 0 0)) => 118" },
    .{ .name = "make-condition-variable", .doc = "Syntax: (make-condition-variable [name])\nLibrary: (srfi 18)\nDescription: Creates a new condition variable, optionally with a name.\nExample:\n  (make-condition-variable 'my-cv)" },
    .{ .name = "make-dict", .doc = "Syntax: (make-dict)\nLibrary: (scm core)\nDescription: Returns a new empty mutable dictionary (hash map) with string or symbol keys.\nExample:\n  (let ((d (make-dict)))\n    (dict-put d \"key\" 42)\n    (dict-get d \"key\")) => 42" },
    .{ .name = "make-directory", .doc = "Syntax: (make-directory path)\nLibrary: (scm fs)\nDescription: Creates the directory named by path, including all intermediate directories.\nExample:\n  (make-directory \"/tmp/new/dir\")" },
    .{ .name = "make-hash-table", .doc = "Syntax: (make-hash-table [equality-proc [hash-proc]])\nLibrary: (srfi 69)\nDescription: Creates a new empty hash table. The optional equality-proc determines key comparison: eq?, eqv?, or equal? (default). The optional hash-proc is accepted but ignored.\nExample:\n  (define ht (make-hash-table equal?))\n  (hash-table-set! ht 'a 1)\n  (hash-table-ref ht 'a) => 1" },
    .{ .name = "make-mutex", .doc = "Syntax: (make-mutex [name])\nLibrary: (srfi 18)\nDescription: Creates a new mutex (mutual exclusion lock), optionally with a name.\nExample:\n  (define m (make-mutex 'my-mutex))" },
    .{ .name = "make-polar", .doc = "Syntax: (make-polar r theta)\nLibrary: (scheme complex)\nDescription: Returns the complex number r * e^(i*theta).\nExample:\n  (make-polar 1 0) => 1.0\n  (make-polar 1 1) => 0.5403023058681398+0.8414709848078965i" },
    .{ .name = "make-record", .doc = "Syntax: (make-record size)\nLibrary: (scm core)\nDescription: Creates a new record with size slots, all initialized to #f.\nExample:\n  (make-record 3) => #<record>" },
    .{ .name = "make-rectangular", .doc = "Syntax: (make-rectangular x y)\nLibrary: (scheme complex)\nDescription: Returns the complex number x + yi.\nExample:\n  (make-rectangular 1 2) => 1+2i\n  (make-rectangular 3 0) => 3" },
    .{ .name = "make-secure-random-port", .doc = "Syntax: (make-secure-random-port)\nLibrary: (srfi 271 randomized)\nDescription: Returns a binary input port delivering an endless stream of\n  cryptographically random bytes. It never returns an eof object.\nExample:\n  (bytevector-length (read-bytevector 16 (make-secure-random-port))) => 16" },
    .{ .name = "make-string", .doc = "Syntax: (make-string k) (make-string k char)\nLibrary: (scheme base) (srfi 13)\nDescription: Returns a newly allocated mutable string of k characters. If char is given, all characters are initialized to char; otherwise they are spaces.\nExample:\n  (make-string 3 #\\x) => \"xxx\"\n  (make-string 3) => \"   \"" },
    .{ .name = "make-symlink", .doc = "Syntax: (make-symlink target linkpath)\nLibrary: (scm fs)\nDescription: Creates a symbolic link at linkpath whose target is the string target, stored verbatim (target need not exist). Does not replace an existing linkpath. Returns unspecified on success, #f on failure. On Windows, requires symlink-creation privilege (Developer Mode or elevation).\nExample:\n  (make-symlink \"../bin/python3\" \"/usr/local/bin/python\")" },
    .{ .name = "make-thread", .doc = "Syntax: (make-thread thunk [name])\nLibrary: (srfi 18)\nDescription: Creates a new thread that will run thunk when started. The thread is not started until thread-start! is called. An optional name can be provided. Note: continuations captured in one thread must not be invoked in another.\nExample:\n  (thread-join! (thread-start! (make-thread (lambda () (+ 1 2))))) => 3" },
    .{ .name = "make-vector", .doc = "Syntax: (make-vector k) (make-vector k fill)\nLibrary: (scheme base)\nDescription: Returns a newly allocated vector of k elements. If fill is given, every element is initialized to fill; otherwise each element is 0.\nExample:\n  (make-vector 3 0) => #(0 0 0)\n  (make-vector 3 'a) => #(a a a)" },
    .{ .name = "md5-hash", .doc = "Syntax: (md5-hash obj)\nLibrary: (scm crypto)\nDescription: Returns the MD5 hash of obj as a lowercase hex string. Accepts strings, symbols, or bytevectors.\nExample:\n  (md5-hash \"hello\") => \"5d41402abc4b2a76b9719d911017c592\"" },
    .{ .name = "member", .doc = "Syntax: (member obj list)\nLibrary: (scheme base)\nDescription: Returns the first sublist of list whose car is equal? to obj, or #f if no such sublist exists.\nExample:\n  (member 'b '(a b c)) => (b c)\n  (member 'd '(a b c)) => #f" },
    .{ .name = "memq", .doc = "Syntax: (memq obj list)\nLibrary: (scheme base)\nDescription: Returns the first sublist of list whose car is eq? to obj, or #f if no such sublist exists.\nExample:\n  (memq 'b '(a b c)) => (b c)\n  (memq 'z '(a b c)) => #f" },
    .{ .name = "memv", .doc = "Syntax: (memv obj list)\nLibrary: (scheme base)\nDescription: Returns the first sublist of list whose car is eqv? to obj, or #f if no such sublist exists.\nExample:\n  (memv 2 '(1 2 3)) => (2 3)\n  (memv 5 '(1 2 3)) => #f" },
    .{ .name = "modulo", .doc = "Syntax: (modulo n1 n2)\nLibrary: (scheme base)\nDescription: Returns the integer modulus of n1 divided by n2. The result has the same sign as n2.\nExample:\n  (modulo 13 4) => 1\n  (modulo -13 4) => 3\n  (modulo 13 -4) => -3" },
    .{ .name = "move-directory", .doc = "Syntax: (move-directory src dest)\nLibrary: (scm fs)\nDescription: Moves (renames) the directory from src to dest. Returns unspecified on success, #f on failure.\nExample:\n  (move-directory \"/tmp/old\" \"/tmp/new\")" },
    .{ .name = "move-file", .doc = "Syntax: (move-file src dest)\nLibrary: (scm fs)\nDescription: Moves (renames) the file from src to dest, overwriting dest if it exists. Returns unspecified on success, #f on failure.\nExample:\n  (move-file \"old.txt\" \"new.txt\")" },
    .{ .name = "mutex-lock!", .doc = "Syntax: (mutex-lock! mutex [timeout [thread]])\nLibrary: (srfi 18)\nDescription: Locks the mutex. If already locked, blocks until available or timeout.\n  Returns #t if locked successfully, #f if timed out. If the mutex was abandoned\n  by a terminated thread, locks it but raises an abandoned-mutex-exception.\nExample:\n  (mutex-lock! m) => #t\n  (mutex-lock! m 0.5) => #f  ; if not acquired within 0.5s" },
    .{ .name = "mutex-name", .doc = "Syntax: (mutex-name mutex)\nLibrary: (srfi 18)\nDescription: Returns the name of the mutex.\nExample:\n  (mutex-name (make-mutex 'my-mutex)) => my-mutex" },
    .{ .name = "mutex-specific", .doc = "Syntax: (mutex-specific mutex)\nLibrary: (srfi 18)\nDescription: Returns the mutex-specific data of the mutex.\nExample:\n  (mutex-specific (make-mutex)) => ()" },
    .{ .name = "mutex-specific-set!", .doc = "Syntax: (mutex-specific-set! mutex obj)\nLibrary: (srfi 18)\nDescription: Sets the mutex-specific data of the mutex to obj.\nExample:\n  (mutex-specific-set! (make-mutex) 42)" },
    .{ .name = "mutex-state", .doc = "Syntax: (mutex-state mutex)\nLibrary: (srfi 18)\nDescription: Returns the state of the mutex: the symbol abandoned, not-owned, not-abandoned, or the owning thread object.\nExample:\n  (mutex-state (make-mutex)) => not-abandoned" },
    .{ .name = "mutex-unlock!", .doc = "Syntax: (mutex-unlock! mutex [condition-variable [timeout]])\nLibrary: (srfi 18)\nDescription: Unlocks the mutex. If a condition-variable is given, the current\n  thread is blocked and added to the condition-variable's wait queue, and the\n  mutex is atomically unlocked. Returns #t if the thread was signaled, #f if\n  timed out.\nExample:\n  (mutex-unlock! m)\n  (mutex-unlock! m cv 1.0)  ; unlock and wait on cv up to 1s" },
    .{ .name = "mutex?", .doc = "Syntax: (mutex? x)\nLibrary: (srfi 18)\nDescription: Returns #t if x is a mutex object.\nExample:\n  (mutex? (make-mutex)) => #t" },
    .{ .name = "newline", .doc = "Syntax: (newline) (newline port)\nLibrary: (scheme write)\nDescription: Writes a newline character to the current output port or to the given port.\nExample:\n  (newline)\n  (newline (open-output-string))" },
    .{ .name = "normalized-path", .doc = "Syntax: (normalized-path path)\nLibrary: (scm fs)\nDescription: Returns the normalized form of path. If absolute, returns the full path; if relative, returns the relative path from the current directory.\nExample:\n  (normalized-path \"./foo/../bar\") => \"bar\"" },
    .{ .name = "not", .doc = "Syntax: (not obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is #f, otherwise returns #f.\nExample:\n  (not #f) => #t\n  (not #t) => #f\n  (not 42) => #f" },
    .{ .name = "null?", .doc = "Syntax: (null? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is the empty list '(), otherwise returns #f.\nExample:\n  (null? '()) => #t\n  (null? '(1 2)) => #f" },
    .{ .name = "number->string", .doc = "Syntax: (number->string z) (number->string z radix)\nLibrary: (scheme base)\nDescription: Returns a string representation of z in the given radix (default 10). Exact integers support any radix.\nExample:\n  (number->string 42) => \"42\"\n  (number->string 255 16) => \"ff\"\n  (number->string 3.14) => \"3.14\"" },
    .{ .name = "number?", .doc = "Syntax: (number? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a number (exact integer, rational, or inexact real), otherwise returns #f.\nExample:\n  (number? 3) => #t\n  (number? 3.5) => #t\n  (number? \"3\") => #f" },
    .{ .name = "open-binary-input-file", .doc = "Syntax: (open-binary-input-file filename)\nLibrary: (scheme file)\nDescription: Opens the named file for binary input and returns a binary input port. Raises a file-error if the file cannot be opened.\nExample:\n  (let ((p (open-binary-input-file \"data.bin\")))\n    (read-u8 p))" },
    .{ .name = "open-binary-output-file", .doc = "Syntax: (open-binary-output-file filename)\nLibrary: (scheme file)\nDescription: Opens the named file for binary output and returns a binary output port. Creates or truncates the file. Raises a file-error on failure.\nExample:\n  (let ((p (open-binary-output-file \"out.bin\")))\n    (write-u8 42 p))" },
    .{ .name = "open-input-bytevector", .doc = "Syntax: (open-input-bytevector bv)\nLibrary: (scheme base)\nDescription: Returns a binary input port that reads bytes from the bytevector bv.\nExample:\n  (let ((p (open-input-bytevector #u8(1 2 3))))\n    (read-u8 p)) => 1" },
    .{ .name = "open-input-file", .doc = "Syntax: (open-input-file filename)\n        (open-input-file filename option ...)\nLibrary: (scheme file)\nDescription: Takes a filename and returns a textual input port that reads characters from the named file. It is an error if the file cannot be opened.\n  As a non-standard extension, up to two optional arguments may follow the filename. They are symbols (strings are also accepted):\n    - an encoding name selects the character encoding (default 'utf-8; also 'latin-1 / 'iso-8859-1, 'utf-16, 'utf-16-le)\n    - 'deflate decompresses a DEFLATE-compressed file while reading (as written by open-output-file ... 'deflate)\nExample:\n  (define p (open-input-file \"data.txt\"))\n  (read-char p) => first character of file\n  (open-input-file \"legacy.txt\" 'latin-1)  ; decode as Latin-1\n  (open-input-file \"data.z\" 'deflate)      ; read compressed input" },
    .{ .name = "open-input-string", .doc = "Syntax: (open-input-string string)\nLibrary: (scheme base)\nDescription: Takes a string and returns a textual input port that delivers characters from the string.\nExample:\n  (define p (open-input-string \"hello\"))\n  (read-char p) => #\\h" },
    .{ .name = "open-input-zip-file", .doc = "Syntax: (open-input-zip-file filename)\nLibrary: (scm zip)\nDescription: Opens an existing ZIP archive at filename for reading and returns a ZIP reader object.\nExample:\n  (define z (open-input-zip-file \"archive.zip\"))\n  (zip-entry-names z)\n  (close-input-zip z)" },
    .{ .name = "open-json-file", .doc = "Syntax: (open-json-file filename)\nLibrary: (scm core)\nDescription: Opens the named JSON file and returns a JSON reader object. An optional list-id symbol may be specified to identify list nodes.\nExample:\n  (define r (open-json-file \"data.json\"))\n  (json-next-object r) => next parsed JSON object" },
    .{ .name = "open-json-string", .doc = "Syntax: (open-json-string s)\nLibrary: (scm json)\nDescription: Returns a JSON reader object that parses the JSON contained in the string s. An optional list-id symbol or string may be specified to identify list nodes.\nExample:\n  (define r (open-json-string \"{\\\"a\\\": 1}\"))\n  (json-next-object r) => parsed object" },
    .{ .name = "open-output-bytevector", .doc = "Syntax: (open-output-bytevector)\nLibrary: (scheme base)\nDescription: Returns a binary output port that accumulates bytes in memory. Use get-output-bytevector to retrieve the accumulated bytes.\nExample:\n  (let ((p (open-output-bytevector)))\n    (write-u8 65 p)\n    (get-output-bytevector p)) => #u8(65)" },
    .{ .name = "open-output-file", .doc = "Syntax: (open-output-file filename)\n        (open-output-file filename option ...)\nLibrary: (scheme file)\nDescription: Takes a filename and returns a textual output port that writes characters to the named file. The file is created or truncated. It is an error if the file cannot be opened.\n  As a non-standard extension, up to three optional arguments may follow the filename. They are symbols (strings are also accepted):\n    - an encoding name selects the character encoding (default 'utf-8; also 'utf-8-bom, 'latin-1 / 'iso-8859-1, 'utf-16, 'utf-16-le)\n    - 'deflate writes a DEFLATE-compressed stream (read it back with open-input-file ... 'deflate)\n    - 'append appends to the file instead of truncating it\nExample:\n  (define p (open-output-file \"out.txt\"))\n  (write-char #\\A p)\n  (open-output-file \"log.txt\" 'append 'latin-1)  ; append, Latin-1\n  (open-output-file \"data.z\" 'deflate)           ; compressed output" },
    .{ .name = "open-output-string", .doc = "Syntax: (open-output-string)\nLibrary: (scheme base)\nDescription: Returns a textual output port that accumulates characters written to it. Use get-output-string to retrieve the accumulated string.\nExample:\n  (let ((p (open-output-string)))\n    (write-char #\\h p)\n    (get-output-string p)) => \"h\"" },
    .{ .name = "open-output-zip-bytevector", .doc = "Syntax: (open-output-zip-bytevector)\nLibrary: (scm zip)\nDescription: Creates a new in-memory ZIP archive and returns a ZIP writer object. After writing entries and calling close-output-zip, use get-output-zip-bytevector to retrieve the bytes.\nExample:\n  (let ((z (open-output-zip-bytevector)))\n    (zip-add-text-entry z \"hello.txt\")\n    (close-output-zip z)\n    (get-output-zip-bytevector z))" },
    .{ .name = "open-output-zip-file", .doc = "Syntax: (open-output-zip-file filename)\nLibrary: (scm core)\nDescription: Creates a new ZIP archive at the given filename and returns a ZIP writer object. Entries can be added using zip-add-text-entry or zip-add-binary-entry.\nExample:\n  (define z (open-output-zip-file \"archive.zip\"))\n  (zip-add-text-entry z \"hello.txt\" \"Hello, world!\")\n  (close-output-zip z)" },
    .{ .name = "open-random-access-file", .doc = "Syntax: (open-random-access-file filename mode)\nLibrary: (scm random access)\nDescription: Opens filename for positioned (random-access) binary I/O and returns a random-access file handle. mode is a symbol or string: read opens an existing file read-only; write creates or truncates the file for read/write; update opens (creating if absent) for read/write without truncating. Raises a file-error on failure.\nExample:\n  (let ((f (open-random-access-file \"data.store\" 'write)))\n    (random-access-file-write! f 0 #u8(1 2 3))\n    (close-random-access-file f))" },
    .{ .name = "open-xml-bytevector", .doc = "Syntax: (open-xml-bytevector bv)\nLibrary: (scm xml)\nDescription: Opens the XML document encoded in the given bytevector and returns an XML reader for forward-only reading of XML nodes. The byte stream is decoded using the XML declaration's encoding, defaulting to UTF-8.\nExample:\n  (define r (open-xml-bytevector (string->utf8 \"<a/>\")))\n  (xml-node-type r) => element" },
    .{ .name = "open-xml-file", .doc = "Syntax: (open-xml-file filename)\nLibrary: (scm core)\nDescription: Opens the named XML file and returns an XML reader object for forward-only reading of XML nodes.\nExample:\n  (define r (open-xml-file \"data.xml\"))\n  (xml-node-type r) => node-type of first node" },
    .{ .name = "open-xml-string", .doc = "Syntax: (open-xml-string source)\nLibrary: (scm xml)\nDescription: Opens the given XML string and returns an XML reader object for forward-only reading of XML nodes.\nExample:\n  (define r (open-xml-string \"<a/>\"))\n  (xml-node-type r) => element" },
    .{ .name = "output-port-open?", .doc = "Syntax: (output-port-open? port)\nLibrary: (scheme base)\nDescription: Returns #t if port is still open, otherwise returns #f.\nExample:\n  (define p (open-output-string))\n  (output-port-open? p) => #t\n  (close-output-port p)\n  (output-port-open? p) => #f" },
    .{ .name = "output-port?", .doc = "Syntax: (output-port? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is an output port, otherwise returns #f.\nExample:\n  (output-port? (open-output-string)) => #t\n  (output-port? (current-output-port)) => #t\n  (output-port? 42) => #f" },
    .{ .name = "pair?", .doc = "Syntax: (pair? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a pair, otherwise returns #f.\nExample:\n  (pair? '(a b c)) => #t\n  (pair? '()) => #f\n  (pair? '(a . b)) => #t\n  (pair? 7) => #f" },
    .{ .name = "parent-pid", .doc = "Syntax: (parent-pid)\nLibrary: (scm system)\nDescription: Returns the OS process id of the parent of the current\n  Scheme process, or #f if it cannot be determined.\nExample:\n  (parent-pid) => 12340" },
    .{ .name = "path-exists?", .doc = "Syntax: (path-exists? path)\nLibrary: (scm fs)\nDescription: Returns #t if path exists as a file, directory, or symbolic link (a dangling link still counts), without following links; otherwise #f. This is the lexists-style check.\nExample:\n  (path-exists? \"/etc/hosts\") => #t" },
    .{ .name = "pbkdf2-sha256", .doc = "Syntax: (pbkdf2-sha256 password salt iterations length)\nLibrary: (scm crypto)\nDescription: Derives a key using PBKDF2-HMAC-SHA256. Password is a string or bytevector, salt is a bytevector. Returns a bytevector of given length.\nExample:\n  (pbkdf2-sha256 \"password\" salt-bv 4096 32) => #u8(...)" },
    .{ .name = "peek-char", .doc = "Syntax: (peek-char)\nLibrary: (scheme base)\nDescription: Returns the next character available from the input port without updating the port to point past the character. If no more characters are available, an end-of-file object is returned. If port is omitted, the current input port is used.\nExample:\n  (define p (open-input-string \"ab\"))\n  (peek-char p) => #\\a\n  (read-char p) => #\\a" },
    .{ .name = "peek-u8", .doc = "Syntax: (peek-u8 port)\nLibrary: (scheme base)\nDescription: Returns the next byte available from the binary input port without consuming it. Returns an end-of-file object if no bytes are available.\nExample:\n  (let ((p (open-input-bytevector #u8(10 20))))\n    (peek-u8 p)) => 10" },
    .{ .name = "pg-parse-datarow", .doc = "Syntax: (pg-parse-datarow body)\nLibrary: (scm core)\nDescription: Parses a PostgreSQL DataRow message body bytevector and returns a vector with one element per column. Each element is a UTF-8 decoded string, an empty string for zero-length values, or #f for NULL. body must point at the column-count int16; the 5-byte type+length frame must already be stripped.\nExample:\n  (pg-parse-datarow body) => #(\"1\" \"alice\" #f)" },
    .{ .name = "pg-quote-literal", .doc = "Syntax: (pg-quote-literal s)\nLibrary: (scm database postgres)\nDescription: Returns s wrapped in single quotes with internal single quotes doubled — the SQL standard string-literal escape, safe under PostgreSQL's default standard_conforming_strings=on (backslashes stay literal). Use for any user-controlled string interpolated into SQL.\nExample:\n  (pg-quote-literal \"O'Brien\") => \"'O''Brien'\"" },
    .{ .name = "pgrep", .doc = "Syntax: (pgrep pattern [full?])\nLibrary: (scm system)\nDescription: Returns a list of pids whose command matches the substring\n  pattern. By default matches against the process name. If full? is #t,\n  matches against the full command line (where the platform supplies it).\n  Pattern matching is case-sensitive substring.\nExample:\n  (pgrep \"java\") => (1234 5678)" },
    .{ .name = "pkill", .doc = "Syntax: (pkill pattern [force? [full?]])\nLibrary: (scm system)\nDescription: Sends a termination request to every process whose command\n  matches the substring pattern. By default matches against the process\n  name; if full? is #t, matches against the full command line. With\n  force? = #t kills forcefully (SIGKILL on Unix). Returns the number of\n  processes that were successfully signaled. Does NOT match the current\n  Scheme process.\nExample:\n  (pkill \"sleep\") => 2" },
    .{ .name = "port-position", .doc = "Syntax: (port-position port)\nLibrary: (scm core)\nDescription: Returns the current position of the textual input port as a list (filename line column): line 1-based, column 0-based, filename \"{string}\" for string ports.\nExample:\n  (define p (open-input-string \"hello\"))\n  (port-position p) => (\"{string}\" 1 0)" },
    .{ .name = "primitive?", .doc = "Syntax: (primitive? obj)\nLibrary: (scm core)\nDescription: Returns #t if obj is a built-in primitive procedure, otherwise returns #f.\nExample:\n  (primitive? car) => #t\n  (primitive? (lambda (x) x)) => #f" },
    .{ .name = "procedure-doc", .doc = "Syntax: (procedure-doc obj)\nLibrary: (scm core)\nDescription: Returns the documentation string for obj as a Scheme string, or #f\n  if no documentation is available. obj may be a procedure, primitive, macro,\n  or symbol naming one.\nExample:\n  (string? (procedure-doc car)) => #t" },
    .{ .name = "process-alive?", .doc = "Syntax: (process-alive? handle)\nLibrary: (scm system)\nDescription: Returns #t if the process started by start-program is still running, #f if it has exited.\nExample:\n  (process-alive? p) => #t" },
    .{ .name = "process-kill", .doc = "Syntax: (process-kill handle [force?])\nLibrary: (scm system)\nDescription: Stops a process started by start-program. With force? = #f (default) requests a normal termination (SIGTERM on Unix, TerminateProcess on Windows via Process.destroy). With force? = #t kills forcefully (SIGKILL on Unix). Returns #t.\nExample:\n  (process-kill p)        ; graceful where supported\n  (process-kill p #t)     ; force" },
    .{ .name = "process-kill-on-exit", .doc = "Syntax: (process-kill-on-exit handle)\nLibrary: (scm system)\nDescription: Registers a process started by start-program to be killed forcefully when this (parent) process exits, via a JVM shutdown hook fired on SIGINT, SIGTERM, SIGHUP and normal exit. Prevents orphaned children — e.g. a dev supervisor's server child left holding a port after the supervisor is stopped. Already-exited handles are pruned, so the registry stays bounded across repeated restarts. Returns #t.\nExample:\n  (define p (start-program '(\"scm\" \"server.scm\")))\n  (process-kill-on-exit p)" },
    .{ .name = "process-pid", .doc = "Syntax: (process-pid handle)\nLibrary: (scm system)\nDescription: Returns the OS process id of a process handle returned by start-program.\nExample:\n  (process-pid p) => 12345" },
    .{ .name = "process-wait", .doc = "Syntax: (process-wait handle [timeout-ms])\nLibrary: (scm system)\nDescription: Waits for the process to exit. Without timeout-ms, blocks until exit and returns the exit code as an integer. With timeout-ms, waits at most that long; returns the exit code on exit, or #f if the process is still running when the timeout elapses.\nExample:\n  (process-wait p)            => 0\n  (process-wait p 5000)       => 0 or #f" },
    .{ .name = "ps", .doc = "Syntax: (ps)\nLibrary: (scm system)\nDescription: Returns a list of alists describing the processes currently\n  visible on the system. Each alist has the keys:\n    pid         — process id (integer)\n    ppid        — parent pid (integer) or #f\n    command     — process command as a string, or #f\n    user        — owning user (string) or #f\n    start-time  — epoch milliseconds (integer) or #f\n    cpu-time    — accumulated cpu time in seconds (inexact) or #f\n  Fields the platform cannot supply or that the current user cannot\n  access are #f. Order is unspecified.\nExample:\n  (length (ps)) => 312" },
    .{ .name = "ps-info", .doc = "Syntax: (ps-info pid)\nLibrary: (scm system)\nDescription: Returns an alist describing the process with the given pid,\n  or #f if no such process exists or it cannot be inspected. See (ps)\n  for the field set.\nExample:\n  (cdr (assq 'command (ps-info (current-pid)))) => \"scm\"" },
    .{ .name = "quotient", .doc = "Syntax: (quotient n1 n2)\nLibrary: (scheme base)\nDescription: Returns the integer quotient of n1 divided by n2, truncated toward zero.\nExample:\n  (quotient 13 4) => 3" },
    .{ .name = "random-access-file-flush", .doc = "Syntax: (random-access-file-flush f)\nLibrary: (scm random access)\nDescription: Flushes any buffered writes for random-access file f to the underlying storage. Returns an unspecified value.\nExample:\n  (random-access-file-flush f)" },
    .{ .name = "random-access-file-read", .doc = "Syntax: (random-access-file-read f offset count)\nLibrary: (scm random access)\nDescription: Reads up to count bytes from random-access file f starting at byte offset and returns them as a freshly allocated bytevector. The returned bytevector is shorter than count (possibly empty) when the read reaches end of file. Does not affect any other read or write.\nExample:\n  (random-access-file-read f 0 4) => #u8(1 2 3 4)" },
    .{ .name = "random-access-file-size", .doc = "Syntax: (random-access-file-size f)\nLibrary: (scm random access)\nDescription: Returns the current size of random-access file f in bytes.\nExample:\n  (random-access-file-size f) => 1024" },
    .{ .name = "random-access-file-truncate!", .doc = "Syntax: (random-access-file-truncate! f size)\nLibrary: (scm random access)\nDescription: Sets the length of random-access file f to size bytes. Shrinks the file when size is smaller than the current length; extends it with zero bytes when larger. Returns an unspecified value.\nExample:\n  (random-access-file-truncate! f 0)" },
    .{ .name = "random-access-file-write!", .doc = "Syntax: (random-access-file-write! f offset bv [start [end]])\nLibrary: (scm random access)\nDescription: Writes the bytes bv[start..end) to random-access file f starting at byte offset, extending the file when the write goes past the current end. start defaults to 0 and end to the length of bv. Returns the number of bytes written.\nExample:\n  (random-access-file-write! f 0 #u8(1 2 3)) => 3" },
    .{ .name = "random-access-file?", .doc = "Syntax: (random-access-file? obj)\nLibrary: (scm random access)\nDescription: Returns #t if obj is a random-access file handle (as returned by open-random-access-file), otherwise #f.\nExample:\n  (random-access-file? (open-random-access-file \"x\" 'write)) => #t\n  (random-access-file? 42) => #f" },
    .{ .name = "random-bytes", .doc = "Syntax: (random-bytes n)\nLibrary: (scm crypto)\nDescription: Returns a fresh bytevector of n cryptographically random bytes.\nExample:\n  (random-bytes 16) => #u8(...)" },
    .{ .name = "rational-denominator", .doc = "Syntax: (rational-denominator q)\nLibrary: (scm core)\nDescription: Returns the denominator of the rational number q in lowest terms. Returns 1 for integers.\n  For inexact rational numbers, returns the denominator as an inexact number.\nExample:\n  (rational-denominator 1/3) => 3\n  (rational-denominator 5)   => 1\n  (rational-denominator 1.5) => 2.0" },
    .{ .name = "rational-numerator", .doc = "Syntax: (rational-numerator q)\nLibrary: (scm core)\nDescription: Returns the numerator of the rational number q in lowest terms. Returns q itself for integers.\n  For inexact rational numbers, returns the numerator as an inexact number.\nExample:\n  (rational-numerator 1/3) => 1\n  (rational-numerator 5)   => 5\n  (rational-numerator 1.5) => 3.0" },
    .{ .name = "read", .doc = "Syntax: (read)\nLibrary: (scheme read)\nDescription: Reads an external representation of a Scheme object from the given port and returns the object. If no more objects are available, an end-of-file object is returned. If port is omitted, the current input port is used.\nExample:\n  (define p (open-input-string \"(a b c)\"))\n  (read p) => (a b c)" },
    .{ .name = "read-bytevector", .doc = "Syntax: (read-bytevector k port)\nLibrary: (scheme base)\nDescription: Reads up to k bytes from the binary input port and returns them as a freshly allocated bytevector. Returns an end-of-file object if no bytes are available.\nExample:\n  (let ((p (open-input-bytevector #u8(1 2 3))))\n    (read-bytevector 2 p)) => #u8(1 2)" },
    .{ .name = "read-bytevector!", .doc = "Syntax: (read-bytevector! bv port)\nLibrary: (scheme base)\nDescription: Reads bytes from the binary input port into the bytevector bv, starting at start (default 0) and ending before end (default length of bv). Returns the number of bytes read, or an end-of-file object if no bytes were available.\nExample:\n  (let ((bv (make-bytevector 3 0))\n        (p (open-input-bytevector #u8(1 2 3))))\n    (read-bytevector! bv p)\n    bv) => #u8(1 2 3)" },
    .{ .name = "read-char", .doc = "Syntax: (read-char)\nLibrary: (scheme base)\nDescription: Returns the next character available from the input port, updating the port to point past the character. If no more characters are available, an end-of-file object is returned. If port is omitted, the current input port is used.\nExample:\n  (define p (open-input-string \"ab\"))\n  (read-char p) => #\\a\n  (read-char p) => #\\b" },
    .{ .name = "read-chars", .doc = "Syntax: (read-chars n port)\nLibrary: (scm io)\nDescription: Reads up to n characters from the textual input port and returns them as a string. Returns an end-of-file object if no characters are available.\nExample:\n  (define p (open-input-string \"hello\"))\n  (read-chars 3 p) => \"hel\"" },
    .{ .name = "read-data", .doc = "Syntax: (read-data port [max-depth])\nLibrary: (scm io)\nDescription: Like read, for data from an untrusted source (uploads,\n  pasted text, network). Datum labels (#0= and #0#) are rejected, so\n  the result never shares structure or contains cycles, and lists,\n  vectors and quote forms may nest at most max-depth levels (default\n  1000). Either violation raises a read error (read-error? is true)\n  instead of building a cyclic datum or exhausting the stack. Returns\n  an end-of-file object at the end of the input.\nExample:\n  (read-data (open-input-string \"(a (b c))\")) => (a (b c))\n  (read-data (open-input-string \"#0=(a . #0#)\")) => read error\n  (read-data (open-input-string \"((x))\") 1) => read error" },
    .{ .name = "read-error?", .doc = "Syntax: (read-error? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is an object representing an error that occurred while reading, otherwise returns #f.\nExample:\n  (read-error? (guard (e (#t e)) (read (open-input-string \"(\")))) => #t" },
    .{ .name = "read-line", .doc = "Syntax: (read-line)\nLibrary: (scheme base)\nDescription: Returns the next line of text available from the input port as a string, discarding the newline. If end of file is reached before any characters are read, an end-of-file object is returned. If port is omitted, the current input port is used.\nExample:\n  (define p (open-input-string \"hello\\nworld\"))\n  (read-line p) => \"hello\"\n  (read-line p) => \"world\"" },
    .{ .name = "read-symlink", .doc = "Syntax: (read-symlink path)\nLibrary: (scm fs)\nDescription: Returns the raw target string stored in the symbolic link at path, exactly as recorded (not resolved or canonicalized). Returns #f if path is not a symbolic link or cannot be read.\nExample:\n  (read-symlink \"/usr/local/bin/python\") => \"../bin/python3\"" },
    .{ .name = "read-u8", .doc = "Syntax: (read-u8 port)\nLibrary: (scheme base)\nDescription: Returns the next byte available from the binary input port as an exact integer in the range 0 to 255. Returns an end-of-file object if no bytes are available.\nExample:\n  (let ((p (open-input-bytevector #u8(65 66))))\n    (read-u8 p)) => 65" },
    .{ .name = "real?", .doc = "Syntax: (real? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a real number, otherwise returns #f. Integers and rationals are also real numbers.\nExample:\n  (real? 3) => #t\n  (real? 3.5) => #t\n  (real? 1/3) => #t\n  (real? \"hello\") => #f" },
    .{ .name = "record-ref", .doc = "Syntax: (record-ref record index)\nLibrary: (scm core)\nDescription: Returns the value of the record slot at the given index.\nExample:\n  (let ((r (make-record 3))) (record-set! r 0 'a) (record-ref r 0)) => a" },
    .{ .name = "record-set!", .doc = "Syntax: (record-set! record index value)\nLibrary: (scm core)\nDescription: Sets the record slot at the given index to value.\nExample:\n  (let ((r (make-record 3))) (record-set! r 0 'hello) (record-ref r 0)) => hello" },
    .{ .name = "record?", .doc = "Syntax: (record? obj)\nLibrary: (scm core)\nDescription: Returns #t if obj is a record, #f otherwise.\nExample:\n  (record? (make-record 3)) => #t\n  (record? #(1 2 3)) => #f" },
    .{ .name = "regex-search", .doc = "Syntax: (regex-search s pattern [start])\nLibrary: (scm string)\nDescription: Searches s for the first match of the regular expression\npattern at or after index start (default 0). Returns a vector with one\nentry per group, the whole match first: each entry is a pair\n(start . end) of string indexes, or #f for a group that does not take\npart in the match. Returns #f if there is no match. Lookbehind, \\b and\n^ see the characters before start, so ^ only matches at index 0 unless\nthe pattern enables multi-line mode with (?m). The pattern syntax is\nthat of the host regex engine (java.util.regex or .NET Regex); the\ncommon subset (classes, quantifiers, groups, (?i), (?m), lookaround)\nbehaves the same in both.\nExample:\n  (regex-search \"abc123\" \"([a-z]+)([0-9]+)\") => #((0 . 6) (0 . 3) (3 . 6))\n  (regex-search \"ab ab\" \"ab\" 1) => #((3 . 5))\n  (regex-search \"b\" \"(x)?b\") => #((0 . 1) #f)\n  (regex-search \"hello\" \"xyz\") => #f" },
    .{ .name = "remainder", .doc = "Syntax: (remainder n1 n2)\nLibrary: (scheme base)\nDescription: Returns the remainder of dividing n1 by n2. The result has the same sign as n1. It is an error if n2 is zero.\nExample:\n  (remainder 13 4) => 1\n  (remainder -13 4) => -1\n  (remainder 13 -4) => 1" },
    .{ .name = "reverse", .doc = "Syntax: (reverse list)\nLibrary: (scheme base)\nDescription: Returns a newly allocated list containing the elements of list in reverse order.\nExample:\n  (reverse '(1 2 3)) => (3 2 1)\n  (reverse '()) => ()" },
    .{ .name = "rgba->jpeg", .doc = "Syntax: (rgba->jpeg pixels width height quality)\nLibrary: (scm image)\nDescription: Encodes straight RGBA pixels as a baseline JPEG (YCbCr 4:2:0,\n  the standard tables scaled to quality 1 to 100), alpha composited over\n  white. Returns the JPEG as a bytevector. Used by image->jpeg." },
    .{ .name = "rgba-split", .doc = "Syntax: (rgba-split pixels components)\nLibrary: (scm pdf)\nDescription: Splits straight RGBA pixels (a bytevector, 4 bytes per\n  pixel) into (color alpha): color has components 3 (RGB) or 1 (gray,\n  taken from the red byte) bytes per pixel, alpha 1; alpha is #f when\n  every pixel is opaque. Used by pdf-embed-png." },
    .{ .name = "round", .doc = "Syntax: (round z)\nLibrary: (scheme base)\nDescription: Returns the integer closest to z. If z is halfway between two integers, rounds to the even one (banker's rounding).\nExample:\n  (round 3.5) => 4.0\n  (round 2.5) => 2.0\n  (round 7/2) => 4" },
    .{ .name = "rsa-decrypt", .doc = "Syntax: (rsa-decrypt private-key ciphertext)\nLibrary: (scm crypto)\nDescription: Decrypts ciphertext using RSA with OAEP-SHA256 padding. private-key must be a bytevector in PKCS#8 DER format (as returned by rsa-generate-keypair). Returns a bytevector.\nExample:\n  (rsa-decrypt priv ciphertext) => #u8(...)" },
    .{ .name = "rsa-encrypt", .doc = "Syntax: (rsa-encrypt public-key plaintext)\nLibrary: (scm crypto)\nDescription: Encrypts plaintext using RSA with OAEP-SHA256 padding. public-key must be a bytevector in SubjectPublicKeyInfo DER format (as returned by rsa-generate-keypair). Returns a bytevector.\nExample:\n  (rsa-encrypt pub plaintext) => #u8(...)" },
    .{ .name = "rsa-generate-keypair", .doc = "Syntax: (rsa-generate-keypair bits)\nLibrary: (scm crypto)\nDescription: Generates an RSA key pair of the given bit size (e.g. 2048, 4096). Returns a list of two bytevectors: (list public-key private-key). The public key is in SubjectPublicKeyInfo DER format; the private key is in PKCS#8 DER format.\nExample:\n  (define kp (rsa-generate-keypair 2048))\n  (define pub (car kp))\n  (define priv (cadr kp))" },
    .{ .name = "run-program", .doc = "Syntax: (run-program cmd [options])\nLibrary: (scm system)\nDescription: Executes the external program specified as a list (program arg1 arg2 ...), waits for it to complete, and returns its exit code as an exact integer. The program inherits the caller's standard input, output and error (so it can use the terminal; start-program gives it a private stdin instead). options is an alist with optional keys: 'work-dir <path>, 'env <alist of (name value) string pairs added to the child environment>. Returns #f on failure.\nExample:\n  (run-program '(\"echo\" \"hello\")) => 0" },
    .{ .name = "run-program/capture", .doc = "Syntax: (run-program/capture cmd [options])\nLibrary: (scm system)\nDescription: Executes the external program specified as a list (program arg1 arg2 ...), waits for it to complete, and returns a list (exit-code stdout stderr) where stdout and stderr are captured as strings. options is an alist with optional keys: 'work-dir <path>, 'stdin <string> (text to write to the child's standard input), 'env <alist of (name value) string pairs added to the child environment>. Returns #f on failure.\nExample:\n  (run-program/capture '(\"echo\" \"hello\")) => (0 \"hello\\n\" \"\")" },
    .{ .name = "scrypt", .doc = "Syntax: (scrypt password salt n r p length)\nLibrary: (scm crypto)\nDescription: Derives a key using scrypt (RFC 7914). Password is a string (UTF-8) or bytevector, salt is a bytevector. n is the CPU/memory cost (a power of 2 greater than 1), r the block size, p the parallelization. Returns a bytevector of given length.\nExample:\n  (scrypt \"password\" salt-bv 32768 8 1 64) => #u8(...)" },
    .{ .name = "second", .doc = "Syntax: (second list)\nLibrary: (srfi 1)\nDescription: Returns the second element of a list. Equivalent to (cadr list).\nExample:\n  (second '(a b c)) => b\n  (second '(1 2 3)) => 2" },
    .{ .name = "secure-random-port?", .doc = "Syntax: (secure-random-port? obj)\nLibrary: (srfi 271 randomized)\nDescription: Returns #t if obj is a port made by make-secure-random-port.\nExample:\n  (secure-random-port? (make-secure-random-port)) => #t" },
    .{ .name = "set-car!", .doc = "Syntax: (set-car! pair obj)\nLibrary: (scheme base)\nDescription: Stores obj in the car field of pair. It is an error if pair is not a pair.\nExample:\n  (define p (list 1 2 3))\n  (set-car! p 'a)\n  p => (a 2 3)" },
    .{ .name = "set-cdr!", .doc = "Syntax: (set-cdr! pair obj)\nLibrary: (scheme base)\nDescription: Stores obj in the cdr field of pair. It is an error if pair is not a pair.\nExample:\n  (define p (list 1 2 3))\n  (set-cdr! p '(b c))\n  p => (1 b c)" },
    .{ .name = "set-current-directory!", .doc = "Syntax: (set-current-directory! path)\nLibrary: (scm core)\nDescription: Sets the process working directory hint to path. Returns the new directory as a string on success, #f on failure. Note: in the JVM the OS-level cwd cannot be changed for already-loaded native code; the value is recorded so that subsequent relative-path operations and child-process invocations behave as if cwd were path.\nExample:\n  (set-current-directory! \"/tmp\") => \"/tmp\"" },
    .{ .name = "set-exit-code!", .doc = "Syntax: (set-exit-code! code)\nLibrary: (scheme process-context)\nDescription: Records the exit code the process should return when the\n  current script finishes, without terminating immediately (unlike exit).\n  The standalone script runner honours this after the script completes.\n  code must be an exact integer. Returns an unspecified value.\nExample:\n  (set-exit-code! 1)" },
    .{ .name = "set-file-modification-time!", .doc = "Syntax: (set-file-modification-time! path millis)\nLibrary: (scm fs)\nDescription: Sets the last-modification time of the file or directory at path to millis (milliseconds since the Unix epoch, UTC). Returns unspecified on success, #f on failure. The unit matches the value returned by file-modification-timestamp.\nExample:\n  (set-file-modification-time! \"dir\" (file-modification-timestamp \"src\"))" },
    .{ .name = "sha1-hash", .doc = "Syntax: (sha1-hash obj)\nLibrary: (scm crypto)\nDescription: Returns the SHA-1 hash of obj as a lowercase hex string. Accepts strings, symbols, or bytevectors.\nExample:\n  (sha1-hash \"hello\") => \"aaf4c61ddcc5e8a2dabede0f3b482cd9aea9434d\"" },
    .{ .name = "sha256-file", .doc = "Syntax: (sha256-file path)\nLibrary: (scm crypto)\nDescription: Returns the SHA-256 hash of the contents of the file at path as a bytevector. The file\n  is read in pieces, so it may be larger than memory.\nExample:\n  (bytevector->hex (sha256-file \"upload.bin\")) => \"9f86d0...\"" },
    .{ .name = "sha256-hash", .doc = "Syntax: (sha256-hash obj)\nLibrary: (scm crypto)\nDescription: Returns the SHA-256 hash of obj as a bytevector. Accepts strings, symbols, or bytevectors.\nExample:\n  (sha256-hash \"hello\") => #u8(...)" },
    .{ .name = "sin", .doc = "Syntax: (sin z)\nLibrary: (scheme inexact)\nDescription: Returns the sine of z, where z is in radians. Returns an inexact result.\nExample:\n  (sin 0) => 0.0\n  (sin (/ (acos -1) 2)) => 1.0" },
    .{ .name = "socket-binary-input-port", .doc = "Syntax: (socket-binary-input-port socket)\nLibrary: (scm net sockets)\nDescription: Returns the binary input port for reading raw bytes from the socket.\nExample:\n  (read-u8 (socket-binary-input-port sock))" },
    .{ .name = "socket-binary-output-port", .doc = "Syntax: (socket-binary-output-port socket)\nLibrary: (scm net sockets)\nDescription: Returns the binary output port for writing raw bytes to the socket.\nExample:\n  (write-u8 65 (socket-binary-output-port sock))" },
    .{ .name = "socket-close", .doc = "Syntax: (socket-close socket-or-listener)\nLibrary: (scm net sockets)\nDescription: Closes a socket or TCP listener.\nExample:\n  (socket-close sock)" },
    .{ .name = "socket-input-port", .doc = "Syntax: (socket-input-port socket)\nLibrary: (scm net sockets)\nDescription: Returns the textual input port for reading from the socket.\nExample:\n  (read-line (socket-input-port sock))" },
    .{ .name = "socket-output-port", .doc = "Syntax: (socket-output-port socket)\nLibrary: (scm net sockets)\nDescription: Returns the textual output port for writing to the socket.\nExample:\n  (display \"hello\" (socket-output-port sock))" },
    .{ .name = "socket-read-line", .doc = "Syntax: (socket-read-line socket)\nLibrary: (scm net sockets)\nDescription: Reads one line directly from the socket's raw underlying stream, byte\n  by byte with no buffering, decoding the bytes as UTF-8. A trailing CR is dropped\n  and the line is terminated by LF; the returned string does not include the line\n  ending. Returns an end-of-file object if the stream is closed before any byte is\n  read. Because it never buffers ahead, it is safe for line-oriented protocols (such\n  as SMTP) where a buffered reader would consume bytes past a protocol boundary like\n  a STARTTLS upgrade.\nExample:\n  (socket-read-line sock) => \"220 mail.example.com ESMTP\"" },
    .{ .name = "socket-starttls!", .doc = "Syntax: (socket-starttls! socket host)\nSyntax: (socket-starttls! socket host verify?)\nLibrary: (scm net sockets)\nDescription: Upgrades an already-connected plaintext socket to TLS in place (the\n  STARTTLS mechanism of SMTP/IMAP/etc.). Wraps the socket's raw underlying stream in\n  a TLS stream and rebuilds the socket's input and output ports over it, so subsequent\n  socket-input-port / socket-output-port use the encrypted channel. host is the server\n  name used for certificate validation. When verify? is omitted or true, the server\n  certificate chain and host name are validated; #f disables validation (insecure).\n  The pre-upgrade dialogue must be read with socket-read-line so no plaintext past the\n  upgrade boundary is buffered. Returns the socket.\nExample:\n  (socket-starttls! sock \"smtp.example.com\")" },
    .{ .name = "socket?", .doc = "Syntax: (socket? x)\nLibrary: (scm net sockets)\nDescription: Returns #t if x is a TCP socket.\nExample:\n  (socket? (tcp-connect \"localhost\" 8080)) => #t" },
    .{ .name = "special-folder-application-data", .doc = "Syntax: (special-folder-application-data)\nLibrary: (scm fs)\nDescription: Returns the path of the user's application data or config directory as a string.\nExample:\n  (special-folder-application-data) => \"/home/user/.config\"" },
    .{ .name = "special-folder-documents", .doc = "Syntax: (special-folder-documents)\nLibrary: (scm fs)\nDescription: Returns the path of the user's documents directory as a string.\nExample:\n  (special-folder-documents) => \"/home/user/Documents\"" },
    .{ .name = "special-folder-temp", .doc = "Syntax: (special-folder-temp)\nLibrary: (scm fs)\nDescription: Returns the platform temp directory path as a string.\nExample: (special-folder-temp) => \"/tmp\"" },
    .{ .name = "special-folder-user-home", .doc = "Syntax: (special-folder-user-home)\nLibrary: (scm fs)\nDescription: Returns the path of the user home directory as a string.\nExample:\n  (special-folder-user-home) => \"/home/user\"" },
    .{ .name = "sql-browser-port", .doc = "Syntax: (sql-browser-port host instance)\nSyntax: (sql-browser-port host instance timeout-ms)\nLibrary: (scm core)\nDescription: Asks the SQL Server Browser service on host (UDP 1434) for the TCP\n  port of the named instance and returns it as an integer. Raises an error when\n  the browser does not answer within timeout-ms (default 5000, two attempts) or\n  the instance has no TCP endpoint. SCM_SQL_BROWSER_PORT overrides the UDP port\n  (for tests).\nExample:\n  (sql-browser-port \"dbhost\" \"SQLEXPRESS\") ; => 49170" },
    .{ .name = "sqrt", .doc = "Syntax: (sqrt z)\nLibrary: (scheme inexact)\nDescription: Returns the principal square root of z. Returns an exact integer when the result is an exact integer, otherwise returns an inexact number.\nExample:\n  (sqrt 4) => 2\n  (sqrt 2) => 1.4142135623730951\n  (sqrt 9) => 3" },
    .{ .name = "start-program", .doc = "Syntax: (start-program cmd-and-args [options])\nLibrary: (scm system)\nDescription: Starts an external program without waiting for it to finish and returns a process handle (a native value). cmd-and-args is a list (program arg1 arg2 ...). options is an alist with optional keys: 'work-dir <path>, 'log-file <path> (redirects stdout+stderr to this file), 'env <alist of (name value) string pairs added to the child environment>. Use process-pid, process-kill, process-wait, process-alive? on the handle.\nExample:\n  (define p (start-program '(\"sleep\" \"30\")))\n  (process-kill p)\n  (process-wait p)" },
    .{ .name = "string", .doc = "Syntax: (string char ...)\nLibrary: (scheme base) (srfi 13)\nDescription: Returns a newly allocated string composed of the given characters.\nExample:\n  (string #\\a #\\b #\\c) => \"abc\"\n  (string) => \"\"" },
    .{ .name = "string->date-days", .doc = "Syntax: (string->date-days s format?)\nLibrary: (scm datetime)\nDescription: Parses the date string s in yyyyMMdd format and returns the number of days since the OLE Automation epoch (December 30, 1899). Returns #f if parsing fails.\nExample:\n  (string->date-days \"20240101\") => 45292\n  (string->date-days \"invalid\") => #f" },
    .{ .name = "string->date-seconds", .doc = "Syntax: (string->date-seconds s format?)\nLibrary: (scm datetime)\nDescription: Parses the date/time string s (in formats like yyyyMMddHHmmss, yyyyMMddHHmm, yyyyMMddHH, or yyyyMMdd) and returns the number of seconds since the Unix epoch. Returns #f if parsing fails.\nExample:\n  (string->date-seconds \"20240101120000\") => 1704110400\n  (string->date-seconds \"invalid\") => #f" },
    .{ .name = "string->latin1", .doc = "Syntax: (string->latin1 s [replacement [start [end]]])\nLibrary: (scm bytevector)\nDescription: Encodes the string s (or its range from start to end) as\nISO-8859-1 (Latin-1) and returns a bytevector. A character above #xFF\n(a surrogate pair counts as one character) is an error unless\nreplacement is given: a byte value 0-255 written in its place.\nExample:\n  (string->latin1 \"a\\xE4;\") => #u8(97 228)\n  (string->latin1 \"a\\x20AC;\" 63) => #u8(97 63)" },
    .{ .name = "string->number", .doc = "Syntax: (string->number s radix?)\nLibrary: (scheme base)\nDescription: Converts the string s to a number using the given radix (default 10). Returns #f if s cannot be parsed as a number.\nExample:\n  (string->number \"42\") => 42\n  (string->number \"ff\" 16) => 255\n  (string->number \"abc\") => #f" },
    .{ .name = "string->symbol", .doc = "Syntax: (string->symbol s)\nLibrary: (scheme base)\nDescription: Returns the interned symbol whose name is the string s. Two calls with equal strings return the same symbol.\nExample:\n  (string->symbol \"hello\") => hello\n  (eq? (string->symbol \"foo\") (string->symbol \"foo\")) => #t" },
    .{ .name = "string->utf8", .doc = "Syntax: (string->utf8 s start? end?)\nLibrary: (scheme base)\nDescription: Returns a bytevector containing the UTF-8 encoding of the string s. Optional start and end indices can be used to encode a substring.\nExample:\n  (string->utf8 \"abc\") => #u8(97 98 99)\n  (string->utf8 \"hello\" 1 3) => #u8(101 108)" },
    .{ .name = "string-append", .doc = "Syntax: (string-append string ...)\nLibrary: (scheme base) (srfi 13)\nDescription: Returns a newly allocated string whose characters are the concatenation of the characters in the given strings.\nExample:\n  (string-append \"foo\" \"bar\") => \"foobar\"\n  (string-append \"a\" \"b\" \"c\") => \"abc\"" },
    .{ .name = "string-contains", .doc = "Syntax: (string-contains s1 s2 [start1 [end1 [start2 [end2]]]])\nLibrary: (srfi 13)\nDescription: Returns the index of the first occurrence of s2[start2..end2) in s1[start1..end1), or #f if not found.\nExample:\n  (string-contains \"hello world\" \"world\") => 6\n  (string-contains \"hello\" \"xyz\") => #f\n  (string-contains \"abcabc\" \"b\" 2) => 4" },
    .{ .name = "string-copy", .doc = "Syntax: (string-copy s start? end?)\nLibrary: (scheme base) (srfi 13)\nDescription: Returns a newly allocated copy of the string s. If start and end are given, only that substring is copied.\nExample:\n  (string-copy \"hello\") => \"hello\"\n  (string-copy \"hello\" 1 3) => \"el\"" },
    .{ .name = "string-downcase", .doc = "Syntax: (string-downcase s)\nLibrary: (scheme char)\nDescription: Returns a string that is the lowercase equivalent of s using full Unicode case mapping." },
    .{ .name = "string-foldcase", .doc = "Syntax: (string-foldcase s)\nLibrary: (scheme char)\nDescription: Returns a string that is the result of applying Unicode case folding to s, which lowercases the string in a locale-independent manner.\nExample:\n  (string-foldcase \"Hello\") => \"hello\"\n  (string-foldcase \"SCHEME\") => \"scheme\"" },
    .{ .name = "string-join", .doc = "Syntax: (string-join strs delim grammar?)\nLibrary: (srfi 13)\nDescription: Concatenates a list of strings strs with delim as the separator. The optional grammar argument may be 'infix (default), 'prefix, or 'suffix.\nExample:\n  (string-join '(\"a\" \"b\" \"c\") \"-\") => \"a-b-c\"\n  (string-join '(\"x\" \"y\") \",\" 'suffix) => \"x,y,\"" },
    .{ .name = "string-length", .doc = "Syntax: (string-length s)\nLibrary: (scheme base) (srfi 13)\nDescription: Returns the number of characters in the string s.\nExample:\n  (string-length \"hello\") => 5\n  (string-length \"\") => 0" },
    .{ .name = "string-matches", .doc = "Syntax: (string-matches s pattern)\nLibrary: (scm string)\nDescription: Matches the string s against the regular expression pattern. Returns a list of match strings (the full match followed by any groups) if successful, or #f if there is no match. A group that does not take part in the match is #f.\nExample:\n  (string-matches \"hello\" \"hel+o\") => (\"hello\")\n  (string-matches \"abc123\" \"([a-z]+)([0-9]+)\") => (\"abc123\" \"abc\" \"123\")\n  (string-matches \"hello\" \"xyz\") => #f" },
    .{ .name = "string-prefix?", .doc = "Syntax: (string-prefix? prefix s)\nLibrary: (srfi 13)\nDescription: Returns #t if prefix is a prefix of s, otherwise returns #f.\nExample:\n  (string-prefix? \"hel\" \"hello\") => #t\n  (string-prefix? \"world\" \"hello\") => #f" },
    .{ .name = "string-ref", .doc = "Syntax: (string-ref s k)\nLibrary: (scheme base) (srfi 13)\nDescription: Returns the character at index k in the string s. It is an error if k is out of range.\nExample:\n  (string-ref \"hello\" 0) => #\\h\n  (string-ref \"hello\" 4) => #\\o" },
    .{ .name = "string-replace-all", .doc = "Syntax: (string-replace-all s pattern replacement)\nLibrary: (scm string)\nDescription: Returns a new string with all occurrences of pattern in s replaced by replacement.\nExample:\n  (string-replace-all \"hello world\" \"world\" \"there\") => \"hello there\"\n  (string-replace-all \"aabbcc\" \"b\" \"x\") => \"aaxxcc\"" },
    .{ .name = "string-replace-all-regex", .doc = "Syntax: (string-replace-all-regex s pattern replacement)\nLibrary: (scm string)\nDescription: Returns a new string with all matches of the regular expression pattern in s replaced by replacement. The replacement may refer to captured groups with ~0 (the whole match), ~1, ~2, ... (parenthesized groups). Use ~~ for a literal tilde. References to groups that did not participate in the match expand to the empty string.\nExample:\n  (string-replace-all-regex \"hello world\" \"o\" \"0\") => \"hell0 w0rld\"\n  (string-replace-all-regex \"2024-01-31\" \"([0-9]+)-([0-9]+)-([0-9]+)\" \"~3.~2.~1\") => \"31.01.2024\"\n  (string-replace-all-regex \"abc123def456\" \"[0-9]+\" \"#\") => \"abc#def#\"" },
    .{ .name = "string-set!", .doc = "Syntax: (string-set! s k char)\nLibrary: (scheme base) (srfi 13)\nDescription: Stores char in position k of the string s, mutating the string in place. It is an error if k is out of range.\nExample:\n  (let ((s (string-copy \"hello\")))\n    (string-set! s 0 #\\H)\n    s) => \"Hello\"" },
    .{ .name = "string-split", .doc = "Syntax: (string-split s pattern?)\nLibrary: (scm string)\nDescription: Splits the string s at occurrences of the regular expression pattern and returns a list of the resulting substrings. Defaults to splitting on whitespace.\nExample:\n  (string-split \"a b c\") => (\"a\" \"b\" \"c\")\n  (string-split \"a,b,c\" \",\") => (\"a\" \"b\" \"c\")" },
    .{ .name = "string-split-vector", .doc = "Syntax: (string-split-vector s pattern?)\nLibrary: (scm string)\nDescription: Splits the string s at occurrences of the regular expression pattern and returns a vector of the resulting substrings. Defaults to splitting on whitespace.\nExample:\n  (string-split-vector \"a b c\") => #(\"a\" \"b\" \"c\")\n  (string-split-vector \"a,b,c\" \",\") => #(\"a\" \"b\" \"c\")" },
    .{ .name = "string-suffix?", .doc = "Syntax: (string-suffix? suffix s)\nLibrary: (srfi 13)\nDescription: Returns #t if suffix is a suffix of s, otherwise returns #f.\nExample:\n  (string-suffix? \"lo\" \"hello\") => #t\n  (string-suffix? \"hi\" \"hello\") => #f" },
    .{ .name = "string-upcase", .doc = "Syntax: (string-upcase s)\nLibrary: (scheme char)\nDescription: Returns a string that is the uppercase equivalent of s using full Unicode case mapping." },
    .{ .name = "string-width", .doc = "Syntax: (string-width s [start [end]])\nLibrary: (scm terminal)\nDescription: Returns the number of terminal columns the string s (or\nits substring from start to end) occupies, summing char-width over its\ncode points. Surrogate pairs count as one code point; control\ncharacters count as 0.\nExample:\n  (string-width \"abc\") => 3\n  (string-width \"\\x4E2D;\\x6587;\") => 4" },
    .{ .name = "string<=?", .doc = "Syntax: (string<=? s1 s2 ...)\nLibrary: (scheme base)\nDescription: Returns #t if the strings are monotonically non-increasing in lexicographic order, otherwise returns #f.\nExample:\n  (string<=? \"a\" \"b\") => #t\n  (string<=? \"abc\" \"abc\") => #t\n  (string<=? \"b\" \"a\") => #f" },
    .{ .name = "string<?", .doc = "Syntax: (string<? s1 s2 ...)\nLibrary: (scheme base)\nDescription: Returns #t if the strings are monotonically increasing in lexicographic order, otherwise returns #f.\nExample:\n  (string<? \"a\" \"b\") => #t\n  (string<? \"abc\" \"abd\") => #t\n  (string<? \"b\" \"a\") => #f" },
    .{ .name = "string=?", .doc = "Syntax: (string=? s1 s2 ...)\nLibrary: (scheme base)\nDescription: Returns #t if all the given strings are equal to each other, otherwise returns #f.\nExample:\n  (string=? \"abc\" \"abc\") => #t\n  (string=? \"abc\" \"def\") => #f\n  (string=? \"x\" \"x\" \"x\") => #t" },
    .{ .name = "string>=?", .doc = "Syntax: (string>=? s1 s2 ...)\nLibrary: (scheme base)\nDescription: Returns #t if the strings are monotonically non-decreasing in lexicographic order, otherwise returns #f.\nExample:\n  (string>=? \"b\" \"a\") => #t\n  (string>=? \"abc\" \"abc\") => #t\n  (string>=? \"a\" \"b\") => #f" },
    .{ .name = "string>?", .doc = "Syntax: (string>? s1 s2 ...)\nLibrary: (scheme base)\nDescription: Returns #t if the strings are monotonically decreasing in lexicographic order, otherwise returns #f.\nExample:\n  (string>? \"b\" \"a\") => #t\n  (string>? \"abc\" \"abc\") => #f\n  (string>? \"c\" \"b\" \"a\") => #t" },
    .{ .name = "string?", .doc = "Syntax: (string? obj)\nLibrary: (scheme base) (srfi 13)\nDescription: Returns #t if obj is a string, otherwise returns #f.\nExample:\n  (string? \"hello\") => #t\n  (string? 42) => #f" },
    .{ .name = "substring", .doc = "Syntax: (substring s start end)\nLibrary: (scheme base)\nDescription: Returns a newly allocated string containing the characters of s from index start (inclusive) to end (exclusive).\nExample:\n  (substring \"hello\" 1 3) => \"el\"\n  (substring \"hello\" 0 5) => \"hello\"" },
    .{ .name = "symbol->string", .doc = "Syntax: (symbol->string sym)\nLibrary: (scheme base)\nDescription: Returns the name of sym as a string.\nExample:\n  (symbol->string 'hello) => \"hello\"\n  (symbol->string 'foo-bar) => \"foo-bar\"" },
    .{ .name = "symbol-starts-with?", .doc = "Syntax: (symbol-starts-with? sym str)\nLibrary: (scm string)\nDescription: Returns #t if the string representation of sym starts with str, #f otherwise. str may be a string or a symbol.\nExample:\n  (symbol-starts-with? 'foobar \"foo\") => #t\n  (symbol-starts-with? 'foobar \"bar\") => #f" },
    .{ .name = "symbol?", .doc = "Syntax: (symbol? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a symbol, #f otherwise.\nExample:\n  (symbol? 'foo) => #t\n  (symbol? \"foo\") => #f" },
    .{ .name = "sys-machine-name", .doc = "Syntax: (sys-machine-name)\nLibrary: (scm system)\nDescription: Returns the hostname of the current machine as a string.\nExample:\n  (sys-machine-name) => \"myhost\"" },
    .{ .name = "sys-num-cpu-cores", .doc = "Syntax: (sys-num-cpu-cores)\nLibrary: (scm system)\nDescription: Returns the number of logical CPU cores available to the current process as an integer.\nExample:\n  (sys-num-cpu-cores) => 8" },
    .{ .name = "sys-os-version", .doc = "Syntax: (sys-os-version)\nLibrary: (scm system)\nDescription: Returns a list describing the operating system: (platform version-string major minor service-pack).\nExample:\n  (sys-os-version) => (linux \"Unix 5.15.0.0\" 5 15 \"\")" },
    .{ .name = "sys-platform", .doc = "Syntax: (sys-platform)\nLibrary: (scm system)\nDescription: Returns a symbol identifying the current operating system platform: windows, linux, or unknown.\nExample:\n  (sys-platform) => linux" },
    .{ .name = "sys-scm-command", .doc = "Syntax: (sys-scm-command)\nLibrary: (scm system)\nDescription: Returns the command line (a list of strings) that starts the currently running SCM interpreter. Append a script path and its arguments to run it with the same implementation (java or csharp) and installation, independent of what scm is on PATH.\nExample:\n  (sys-scm-command) => (\"/usr/lib/jvm/java-21/bin/java\" \"-jar\" \"/opt/dabscm/scm.jar\")\n  (run-program (append (sys-scm-command) (list \"build.scm\")))" },
    .{ .name = "sys-scm-technology", .doc = "Syntax: (sys-scm-technology)\nLibrary: (scm system)\nDescription: Returns a symbol identifying the SCM implementation technology: csharp or java.\nExample:\n  (sys-scm-technology) => java" },
    .{ .name = "sys-scm-version", .doc = "Syntax: (sys-scm-version)\nLibrary: (scm system)\nDescription: Returns the SCM interpreter version as a string.\nExample:\n  (sys-scm-version) => \"0.0.1\"" },
    .{ .name = "sys-user-name", .doc = "Syntax: (sys-user-name)\nLibrary: (scm system)\nDescription: Returns the name of the currently logged-in user as a string.\nExample:\n  (sys-user-name) => \"alice\"" },
    .{ .name = "tan", .doc = "Syntax: (tan z)\nLibrary: (scheme inexact)\nDescription: Returns the trigonometric tangent of z, where z is in radians.\nExample:\n  (tan 0) => 0.0\n  (tan (/ (* 3.14159265 1) 4)) => 1.0" },
    .{ .name = "tcp-accept", .doc = "Syntax: (tcp-accept listener)\nLibrary: (scm net sockets)\nDescription: Accepts an incoming TCP connection on the listener. Blocks until a connection arrives.\nExample:\n  (define sock (tcp-accept listener))" },
    .{ .name = "tcp-connect", .doc = "Syntax: (tcp-connect host port)\nLibrary: (scm net sockets)\nDescription: Connects to a TCP server at the given host and port. Returns a socket.\nExample:\n  (define sock (tcp-connect \"localhost\" 8080))" },
    .{ .name = "tcp-listen", .doc = "Syntax: (tcp-listen port)\nLibrary: (scm net sockets)\nDescription: Creates a TCP listener on the given port and starts listening for connections.\nExample:\n  (define l (tcp-listen 8080))" },
    .{ .name = "tcp-listener?", .doc = "Syntax: (tcp-listener? x)\nLibrary: (scm net sockets)\nDescription: Returns #t if x is a TCP listener.\nExample:\n  (tcp-listener? (tcp-listen 8080)) => #t" },
    .{ .name = "tds-connect", .doc = "Syntax: (tds-connect host port)\nSyntax: (tds-connect host port encrypt? verify? cert-host)\nLibrary: (scm core)\nDescription: Connects to a SQL Server at the given host and port using TDS.\n  port is a TCP port number or an instance name (string), which is resolved\n  through the SQL Server Browser service (see sql-browser-port).\n  Performs the PreLogin exchange and, when encrypt? is true (default), the TLS\n  handshake (wrapped in TDS PRELOGIN packets); the whole session is then encrypted.\n  With verify? true the certificate chain and host name (cert-host, default host)\n  are validated, otherwise any certificate is accepted (default). With encrypt? #f\n  no TLS is used, which fails if the server requires encryption.\n  SCM_TDS_DEBUG=1 prints the negotiation to stderr; SCM_TDS_TLS_PROTOCOLS\n  overrides the enabled TLS versions (default TLSv1.2).\n  Returns a socket suitable for use with the (scm database sqlserver) library.\nExample:\n  (define sock (tds-connect \"localhost\" 1433))" },
    .{ .name = "terminal-byte-ready?", .doc = "Syntax: (terminal-byte-ready? [timeout-ms])\nLibrary: (scm terminal)\nDescription: Returns #t if a byte is available for reading from\nstandard input without blocking, #f otherwise. With timeout-ms,\nwaits up to that many milliseconds for a byte to arrive.\nIntended for use in raw terminal mode to detect multi-byte\nescape sequences.\nExample:\n  (terminal-byte-ready?) => #f\n  (terminal-byte-ready? 50) => #t  ; a key arrived within 50 ms" },
    .{ .name = "terminal-enable-ansi!", .doc = "Syntax: (terminal-enable-ansi!)\nLibrary: (scm terminal)\nDescription: Enables ANSI escape sequence processing.\nOn Windows, this enables virtual terminal processing for the\nconsole output and input handles. On Linux and macOS, this is\na no-op since ANSI is natively supported.\nReturns #t on success, #f on failure.\nNote: In the Java implementation, this is always a no-op.\nWindows ANSI support requires a modern terminal emulator.\nExample:\n  (terminal-enable-ansi!) => #t" },
    .{ .name = "terminal-raw!", .doc = "Syntax: (terminal-raw! enable)\nLibrary: (scm terminal)\nDescription: Enables or disables raw terminal mode.\nWhen enable is #t, disables line buffering, echo, signal processing,\nflow control (Ctrl-S/Ctrl-Q), CR/NL translation of input and output\npost-processing, so that individual keypresses can be read; write\n\"\\r\\n\" to start a new line at column 1.\nWhen enable is #f, restores the original terminal settings.\nReturns #t on success, #f if raw mode is not supported.\nOn Windows with Java, raw mode is not supported and returns #f.\nExample:\n  (terminal-raw! #t)  ; enable raw mode\n  (terminal-raw! #f)  ; restore original mode" },
    .{ .name = "terminal-read-byte", .doc = "Syntax: (terminal-read-byte)\nLibrary: (scm terminal)\nDescription: Reads a single raw byte from standard input, bypassing\nthe port system and any line buffering. Returns an integer 0-255,\nor an eof-object if the end of input has been reached.\nIntended for use in raw terminal mode.\nExample:\n  (terminal-read-byte) => 27  ; ESC key" },
    .{ .name = "terminal-resize-count", .doc = "Syntax: (terminal-resize-count)\nLibrary: (scm terminal)\nDescription: Returns the number of terminal resize events (SIGWINCH)\nseen since resize tracking started, or #f if resize events cannot be\nobserved on this platform. The first call starts tracking and returns 0.\nCompare successive results to find out whether the terminal changed\nsize; while tracking is active, terminal-size is cached between resizes.\nExample:\n  (terminal-resize-count) => 0" },
    .{ .name = "terminal-size", .doc = "Syntax: (terminal-size)\nLibrary: (scm terminal)\nDescription: Returns the terminal dimensions as a pair (cols . rows),\nor #f if the terminal size cannot be determined. While resize tracking\nis active (see terminal-resize-count) the size is cached until the\nnext resize.\nExample:\n  (terminal-size) => (80 . 24)" },
    .{ .name = "terminal?", .doc = "Syntax: (terminal?)\nSyntax: (terminal? which)\nLibrary: (scm terminal)\nDescription: Returns #t if the process is connected to a terminal.\nIf which is 'input, checks only the input stream.\nIf which is 'output, checks only the output stream.\nWith no arguments, returns #t only if both input and output are terminals.\nExample:\n  (terminal?) => #t" },
    .{ .name = "terminated-thread-exception?", .doc = "Syntax: (terminated-thread-exception? obj)\nLibrary: (srfi 18)\nDescription: Returns #t if obj is a terminated-thread exception.\nExample:\n  (terminated-thread-exception? exn)" },
    .{ .name = "textual-port?", .doc = "Syntax: (textual-port? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a textual port (i.e., a port that reads or writes characters), #f otherwise.\nExample:\n  (textual-port? (current-input-port)) => #t\n  (textual-port? (open-output-bytevector)) => #f" },
    .{ .name = "thread-join!", .doc = "Syntax: (thread-join! thread [timeout [timeout-val]])\nLibrary: (srfi 18)\nDescription: Waits for thread to terminate. Returns the thread's result value.\n  If timeout is given and reached, returns timeout-val or raises a\n  join-timeout-exception. If the thread terminated with an uncaught exception,\n  raises an uncaught-exception.\nExample:\n  (thread-join! (thread-start! (make-thread (lambda () 42)))) => 42" },
    .{ .name = "thread-name", .doc = "Syntax: (thread-name thread)\nLibrary: (srfi 18)\nDescription: Returns the name of the thread.\nExample:\n  (thread-name (make-thread (lambda () #t) 'my-thread)) => my-thread" },
    .{ .name = "thread-sleep!", .doc = "Syntax: (thread-sleep! timeout)\nLibrary: (srfi 18)\nDescription: Causes the current thread to sleep until the timeout. Timeout can be a time object, an integer (seconds), or a real (seconds).\nExample:\n  (thread-sleep! 1)" },
    .{ .name = "thread-specific", .doc = "Syntax: (thread-specific thread)\nLibrary: (srfi 18)\nDescription: Returns the thread-specific data of the thread.\nExample:\n  (thread-specific (current-thread)) => ()" },
    .{ .name = "thread-specific-set!", .doc = "Syntax: (thread-specific-set! thread obj)\nLibrary: (srfi 18)\nDescription: Sets the thread-specific data of the thread to obj.\nExample:\n  (thread-specific-set! (current-thread) 42)" },
    .{ .name = "thread-start!", .doc = "Syntax: (thread-start! thread)\nLibrary: (srfi 18)\nDescription: Makes thread runnable. The thread will execute its thunk in a new\n  execution context with its own dynamic environment inherited from the creating\n  thread. Returns the thread.\nExample:\n  (thread-start! (make-thread (lambda () 42)))" },
    .{ .name = "thread-terminate!", .doc = "Syntax: (thread-terminate! thread)\nLibrary: (srfi 18)\nDescription: Terminates the given thread.\nExample:\n  (thread-terminate! thread)" },
    .{ .name = "thread-yield!", .doc = "Syntax: (thread-yield!)\nLibrary: (srfi 18)\nDescription: Causes the current thread to yield the processor.\nExample:\n  (thread-yield!)" },
    .{ .name = "thread?", .doc = "Syntax: (thread? x)\nLibrary: (srfi 18)\nDescription: Returns #t if x is a thread object.\nExample:\n  (thread? (make-thread (lambda () 1))) => #t" },
    .{ .name = "timestamp", .doc = "Syntax: (timestamp)\nLibrary: (scm datetime)\nDescription: Returns the current time as the number of milliseconds since the epoch (January 1, year 1).\nExample:\n  (timestamp) => 63850000000000" },
    .{ .name = "timestamp->string", .doc = "Syntax: (timestamp->string ms format?)\nLibrary: (scm datetime)\nDescription: Formats a timestamp (milliseconds) as a date string. The optional format may be isodatetime, isodate, datetime, date, or a custom .NET format string; defaults to isodatetime.\nExample:\n  (timestamp->string (timestamp)) => \"20260318-153045\"\n  (timestamp->string (timestamp) 'isodate) => \"20260318\"" },
    .{ .name = "tls-connect", .doc = "Syntax: (tls-connect host port)\nSyntax: (tls-connect host port verify?)\nLibrary: (scm net sockets)\nDescription: Connects to a TCP server at host:port and immediately performs a TLS\n  handshake (implicit TLS, as used by SMTPS on port 465 or HTTPS). Returns a socket\n  whose ports read and write encrypted data transparently. When verify? is omitted or\n  true, the server certificate chain and host name are validated; passing #f disables\n  validation (insecure, for testing only).\nExample:\n  (define sock (tls-connect \"smtp.example.com\" 465))" },
    .{ .name = "truncate", .doc = "Syntax: (truncate x)\nLibrary: (scheme base)\nDescription: Returns the integer closest to x whose absolute value is not larger than the absolute value of x (rounds toward zero).\nExample:\n  (truncate 3.7) => 3.0\n  (truncate -3.7) => -3.0" },
    .{ .name = "uncaught-exception-reason", .doc = "Syntax: (uncaught-exception-reason exn)\nLibrary: (srfi 18)\nDescription: Returns the original exception from an uncaught-exception object.\nExample:\n  (uncaught-exception-reason exn)" },
    .{ .name = "uncaught-exception?", .doc = "Syntax: (uncaught-exception? obj)\nLibrary: (srfi 18)\nDescription: Returns #t if obj is an uncaught exception.\nExample:\n  (guard (e ((uncaught-exception? e) (uncaught-exception-reason e)))\n    (thread-join! (thread-start! (make-thread (lambda () (error \"oops\"))))))" },
    .{ .name = "utf8->string", .doc = "Syntax: (utf8->string bv start? end?)\nLibrary: (scheme base)\nDescription: Decodes the UTF-8 encoded bytes in bytevector bv (optionally from start to end) and returns the result as a string.\nExample:\n  (utf8->string #u8(104 101 108 108 111)) => \"hello\"\n  (utf8->string #u8(104 101 108 108 111) 1 3) => \"el\"" },
    .{ .name = "utf8-valid?", .doc = "Syntax: (utf8-valid? bv [start [end]])\nLibrary: (scm bytevector)\nDescription: Returns #t if the bytes of bv (or its range from start to\nend) are well-formed UTF-8, #f otherwise. Use it to decide whether\nutf8->string would replace any bytes with U+FFFD, for example to tell\nUTF-8 files from Latin-1 ones.\nExample:\n  (utf8-valid? (bytevector #xC3 #xA4)) => #t\n  (utf8-valid? (bytevector #xE4)) => #f" },
    .{ .name = "values", .doc = "Syntax: (values obj ...)\nLibrary: (scheme base)\nDescription: Returns all of its arguments as multiple values. Used with call-with-values to pass multiple results between procedures.\nExample:\n  (values 1 2 3) => 1 2 3\n  (call-with-values (lambda () (values 4 5)) +) => 9" },
    .{ .name = "vector", .doc = "Syntax: (vector obj ...)\nLibrary: (scheme base)\nDescription: Returns a newly allocated vector whose elements contain the given arguments.\nExample:\n  (vector 1 2 3) => #(1 2 3)\n  (vector 'a 'b 'c) => #(a b c)" },
    .{ .name = "vector-length", .doc = "Syntax: (vector-length v)\nLibrary: (scheme base)\nDescription: Returns the number of elements in vector v.\nExample:\n  (vector-length #(1 2 3)) => 3\n  (vector-length (vector)) => 0" },
    .{ .name = "vector-ref", .doc = "Syntax: (vector-ref v k)\nLibrary: (scheme base)\nDescription: Returns the element at index k in vector v. If k is out of range and a default is provided, returns the default instead of signalling an error.\nExample:\n  (vector-ref #(a b c) 1) => b\n  (vector-ref #(a b c) 5 'none) => none" },
    .{ .name = "vector-set!", .doc = "Syntax: (vector-set! v k obj)\nLibrary: (scheme base)\nDescription: Stores obj in element k of vector v. It is an error if k is not a valid index of v.\nExample:\n  (let ((v (vector 1 2 3))) (vector-set! v 1 99) v) => #(1 99 3)" },
    .{ .name = "vector?", .doc = "Syntax: (vector? obj)\nLibrary: (scheme base)\nDescription: Returns #t if obj is a vector, #f otherwise.\nExample:\n  (vector? #(1 2 3)) => #t\n  (vector? '(1 2 3)) => #f" },
    .{ .name = "which", .doc = "Syntax: (which program)\nLibrary: (scm fs)\nDescription: Searches the directories in PATH for an executable named program and returns its full path as a string, or #f if not found. On Windows, a program name without an extension is tried with each PATHEXT extension (e.g. \"psql\" finds psql.exe).\nExample:\n  (which \"ls\") => \"/usr/bin/ls\"\n  (which \"nonexistent\") => #f" },
    .{ .name = "write", .doc = "Syntax: (write obj port?)\nLibrary: (scheme write)\nDescription: Writes a machine-readable representation of obj to the given port, or the current output port. Strings are written with quotes and special characters escaped.\nExample:\n  (write '(1 \"two\" #\\3)) => (1 \"two\" #\\3)\n  (write 'hello) => hello" },
    .{ .name = "write-bytevector", .doc = "Syntax: (write-bytevector bv port? start? end?)\nLibrary: (scheme base)\nDescription: Writes the bytes of bytevector bv to binary output port, optionally restricted to the range [start, end).\nExample:\n  (write-bytevector #u8(1 2 3) port)\n  (write-bytevector #u8(1 2 3 4 5) port 1 3)" },
    .{ .name = "write-char", .doc = "Syntax: (write-char char port?)\nLibrary: (scheme base)\nDescription: Writes the character char to the given textual output port, or to the current output port if no port is specified.\nExample:\n  (write-char #\\A) => (outputs A)\n  (write-char #\\newline port)" },
    .{ .name = "write-shared", .doc = "Syntax: (write-shared obj port?)\nLibrary: (scheme write)\nDescription: Writes obj to the given port using datum labels (#N= and #N#) to represent all shared and cyclic structure.\nExample:\n  (let ((x (list 1 2))) (write-shared x)) => (1 2)\n  (write-shared '#0=(a . #0#)) => #0=(a . #0#)" },
    .{ .name = "write-simple", .doc = "Syntax: (write-simple obj port?)\nLibrary: (scheme write)\nDescription: Writes obj to the given port without performing shared-structure detection, making it faster but unable to handle cyclic data.\nExample:\n  (write-simple '(1 2 3)) => (1 2 3)\n  (write-simple \"hello\") => \"hello\"" },
    .{ .name = "write-string", .doc = "Syntax: (write-string string)\n       (write-string string port)\n       (write-string string port start)\n       (write-string string port start end)\nLibrary: (scheme base)\nDescription: Writes the characters of string from start to end in left-to-right order to the given port. port defaults to the current output port. start defaults to 0 and end defaults to the length of string. The native primitive does a single bulk Writer.write(char[], start, count) — large strings don't pay the Scheme→native transition per char.\nExample:\n  (write-string \"hello\")\n  (write-string \"hello\" port 1 3)" },
    .{ .name = "write-u8", .doc = "Syntax: (write-u8 byte port?)\nLibrary: (scheme base)\nDescription: Writes a single byte (an exact integer in the range 0-255) to the given binary output port.\nExample:\n  (write-u8 65 port)\n  (write-u8 0 port)" },
    .{ .name = "xml-attribute", .doc = "Syntax: (xml-attribute xml-reader name)\nLibrary: (scm xml)\nDescription: Returns the value of the named attribute from the current element of xml-reader as a string, or #f if the attribute does not exist.\nExample:\n  (xml-attribute reader \"id\") => \"42\"\n  (xml-attribute reader 'class) => #f" },
    .{ .name = "xml-name", .doc = "Syntax: (xml-name xml-reader)\nLibrary: (scm xml)\nDescription: Returns the qualified name of the current XML element or attribute node as a string.\nExample:\n  (xml-name reader) => \"Customer\"\n  (xml-name reader) => \"ns:Element\"" },
    .{ .name = "xml-node-type", .doc = "Syntax: (xml-node-type xml-reader)\nLibrary: (scm xml)\nDescription: Returns a symbol identifying the type of the current XML node: element, end-element, text, cdata, comment, pi, xml-decl, doc, doc-type, entity-ref, or #f for unrecognized types.\nExample:\n  (xml-node-type reader) => element\n  (xml-node-type reader) => text" },
    .{ .name = "xml-read", .doc = "Syntax: (xml-read xml-reader)\nLibrary: (scm xml)\nDescription: Advances xml-reader to the next node in the XML document. Returns #t if a node was read, or #f if the end of the document was reached.\nExample:\n  (xml-read reader) => #t\n  (xml-read reader) => #f" },
    .{ .name = "xml-read-to", .doc = "Syntax: (xml-read-to xml-reader name)\nLibrary: (scm xml)\nDescription: Advances xml-reader forward until it reaches an element with the given name. Returns #t if found, or #f if the end of the document is reached first.\nExample:\n  (xml-read-to reader \"Customer\") => #t\n  (xml-read-to reader 'Item) => #f" },
    .{ .name = "xml-value", .doc = "Syntax: (xml-value xml-reader)\nLibrary: (scm xml)\nDescription: Reads and returns the text content of the current element as a string, or #f if there is no value.\nExample:\n  (xml-value reader) => \"John Doe\"\n  (xml-value reader) => #f" },
    .{ .name = "xor-key", .doc = "Syntax: (xor-key bv key)\nLibrary: (scm crypto)\nDescription: Returns a new bytevector produced by XORing each byte of bv with the corresponding byte of key, cycling through key as needed.\nExample:\n  (xor-key data-bv key-bv) => #u8(...)" },
    .{ .name = "zip-add-binary-entry", .doc = "Syntax: (zip-add-binary-entry zip name [timestamp])\nLibrary: (scm zip)\nDescription: Creates a new binary entry named name in the ZIP archive zip and\n  returns an output binary port for writing to it. The optional timestamp is a\n  Unix epoch in seconds.\nExample:\n  (let ((port (zip-add-binary-entry zip \"data.bin\"))) (write-bytevector bv port))" },
    .{ .name = "zip-add-file-entry", .doc = "Syntax: (zip-add-file-entry zip name path [compress?])\nLibrary: (scm zip)\nDescription: Adds the file at path to the ZIP archive zip as the entry named name, reading it in\n  pieces, so the file may be larger than memory. The entry is stored uncompressed unless\n  compress? is true: images, videos and other compressed formats gain nothing from deflating.\nExample:\n  (zip-add-file-entry zip \"assets/video.mp4\" \"/var/lib/app/video.mp4\")" },
    .{ .name = "zip-add-stored-entry", .doc = "Syntax: (zip-add-stored-entry zip name bytevector [timestamp])\nLibrary: (scm zip)\nDescription: Creates a new uncompressed (STORED) entry named name in the\n  ZIP archive zip and writes the entire bytevector as its content. Unlike\n  zip-add-binary-entry, the data is stored without compression and must be\n  provided in full. The optional timestamp is a Unix epoch in seconds.\n  Returns void.\nExample:\n  (zip-add-stored-entry zip \"mimetype\" (string->utf8 \"application/xml\") 0)" },
    .{ .name = "zip-add-text-entry", .doc = "Syntax: (zip-add-text-entry zip name [timestamp])\nLibrary: (scm zip)\nDescription: Creates a new text entry named name in the ZIP archive zip and\n  returns a UTF-8 textual output port for writing to it. The optional timestamp\n  is a Unix epoch in seconds.\nExample:\n  (let ((port (zip-add-text-entry zip \"readme.txt\"))) (display \"Hello\" port))" },
    .{ .name = "zip-entry-names", .doc = "Syntax: (zip-entry-names zip)\nLibrary: (scm zip)\nDescription: Returns a list of entry name strings in the ZIP archive zip.\nExample:\n  (zip-entry-names z) => (\"file1.txt\" \"dir/file2.txt\")" },
    .{ .name = "zip-entry-size", .doc = "Syntax: (zip-entry-size zip name)\nLibrary: (scm zip)\nDescription: Returns the uncompressed size in bytes the archive declares for the entry named\n  name, or #f if it declares none. Check it before reading an entry of an archive you did not\n  make (a small archive can unpack to gigabytes); zip-extract-entry also enforces a limit.\nExample:\n  (zip-entry-size z \"hello.txt\") => 5" },
    .{ .name = "zip-extract-entry", .doc = "Syntax: (zip-extract-entry zip name path [max-bytes])\nLibrary: (scm zip)\nDescription: Writes the contents of the entry named name to the file at path, in pieces, so the\n  entry may be larger than memory, and returns the number of bytes written. With max-bytes, an\n  entry that unpacks to more raises an error (whatever size the archive declares) and the\n  partial file is deleted.\nExample:\n  (zip-extract-entry z \"video.mp4\" \"/tmp/video.mp4\" (* 1024 1024 1024)) => 52428800" },
    .{ .name = "zip-read-entry-bytevector", .doc = "Syntax: (zip-read-entry-bytevector zip name)\nLibrary: (scm zip)\nDescription: Reads the contents of the entry named name from the ZIP archive zip and returns it as a bytevector.\nExample:\n  (zip-read-entry-bytevector z \"hello.txt\") => #u8(72 101 108 108 111)" },
    .{ .name = "zlib-compress", .doc = "Syntax: (zlib-compress bytevector [level])\nLibrary: (scm compression)\nDescription: Compresses bytevector using ZLib framing (RFC 1950) and returns\n  a bytevector. The optional level is an integer 0-9: 0 = no compression,\n  1-3 = fastest, 4-6 = optimal (default), 7-9 = smallest size.\nExample:\n  (utf8->string (zlib-decompress (zlib-compress (string->utf8 \"hello\")))) => \"hello\"" },
    .{ .name = "zlib-decompress", .doc = "Syntax: (zlib-decompress bytevector)\nLibrary: (scm compression)\nDescription: Decompresses a ZLib-framed (RFC 1950) bytevector and returns\n  the original bytevector.\nExample:\n  (utf8->string (zlib-decompress (zlib-compress (string->utf8 \"hello\")))) => \"hello\"" },
};
